// 3D Model studio: real GLB meshes in an orbitable three.js viewport. Loaded lazily by main.js.
import * as THREE from 'three';
import { GLTFLoader } from '../vendor/GLTFLoader.js';
import { OrbitControls } from '../vendor/OrbitControls.js';

export function initViewer(host, seg, { reduce }) {
  const state = host.querySelector('#vstate'), tri = host.querySelector('#vtri');
  let renderer;
  try { renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, powerPreference: 'low-power' }); }
  catch (e) { throw new Error('WebGL unavailable'); }
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.75));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.35;
  host.prepend(renderer.domElement);

  const scene = new THREE.Scene();
  const cam = new THREE.PerspectiveCamera(35, 1, .05, 100); cam.position.set(2.3, 1.2, 2.8);
  scene.add(new THREE.HemisphereLight(0xdfe8ff, 0x0a0a14, 1.1));
  const key = new THREE.DirectionalLight(0xffffff, 2.2); key.position.set(3, 4, 2); scene.add(key);
  const rimB = new THREE.DirectionalLight(0x3d7bff, 3.2); rimB.position.set(-4, 1.5, -3); scene.add(rimB);
  const rimV = new THREE.DirectionalLight(0x8b5cff, 2.6); rimV.position.set(4, .5, -4); scene.add(rimV);

  // floor: soft ring + faint polar grid
  const floor = new THREE.Group(); scene.add(floor);
  const grid = new THREE.PolarGridHelper(1.6, 12, 4, 64, 0x3d7bff, 0x22283a); grid.material.transparent = true; grid.material.opacity = .35; floor.add(grid);
  const cv = document.createElement('canvas'); cv.width = cv.height = 128; const cx = cv.getContext('2d');
  const gr = cx.createRadialGradient(64, 64, 0, 64, 64, 64); gr.addColorStop(0, 'rgba(61,123,255,.45)'); gr.addColorStop(1, 'rgba(0,0,0,0)'); cx.fillStyle = gr; cx.fillRect(0, 0, 128, 128);
  const glow = new THREE.Mesh(new THREE.PlaneGeometry(3.4, 3.4), new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(cv), transparent: true, depthWrite: false }));
  glow.rotation.x = -Math.PI / 2; glow.position.y = .001; floor.add(glow);

  const controls = new OrbitControls(cam, renderer.domElement);
  controls.enableDamping = true; controls.enablePan = false; controls.minDistance = 1.8; controls.maxDistance = 7;
  controls.autoRotate = !reduce; controls.autoRotateSpeed = 1.4; controls.target.set(0, .45, 0);
  controls.addEventListener('start', () => { controls.autoRotate = false; });

  const loader = new GLTFLoader(); const cache = {}; let current = null;
  function fit(obj) {
    const box = new THREE.Box3().setFromObject(obj), size = box.getSize(new THREE.Vector3()), ctr = box.getCenter(new THREE.Vector3());
    const s = 2.1 / Math.max(size.x, size.y, size.z); obj.scale.setScalar(s);
    obj.position.set(-ctr.x * s, -box.min.y * s + .05, -ctr.z * s);
  }
  function load(name) {
    state.textContent = 'loading model…'; state.style.display = '';
    const done = (o) => {
      if (current) scene.remove(current); current = o; scene.add(o); state.style.display = 'none';
      let t = 0; o.traverse((m) => { if (m.isMesh) { t += (m.geometry.index ? m.geometry.index.count : m.geometry.attributes.position.count) / 3; } });
      tri.textContent = `${Math.round(t).toLocaleString()} triangles · real .glb`;
      kick();
    };
    if (cache[name]) return done(cache[name]);
    loader.load(`assets/models/${name}.glb`, (g) => { const o = g.scene; fit(o); cache[name] = o; done(o); }, undefined, (err) => { console.warn(err); state.textContent = 'model failed to load'; });
  }
  seg.querySelectorAll('button').forEach((b) => b.addEventListener('click', () => {
    seg.querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', x === b)); load(b.dataset.model);
  }));

  function size() { const r = host.getBoundingClientRect(); renderer.setSize(r.width, r.height, false); cam.aspect = r.width / Math.max(1, r.height); cam.updateProjectionMatrix(); }
  new ResizeObserver(() => { size(); kick(); }).observe(host); size();

  let vis = true, raf = 0, idle = 0, inLoop = false;
  new IntersectionObserver(([en]) => { vis = en.isIntersecting; kick(); }).observe(host);
  document.addEventListener('visibilitychange', kick);
  controls.addEventListener('change', () => { idle = 0; if (!inLoop) kick(); });
  function loop() {
    raf = 0; if (!vis || document.hidden) return;
    inLoop = true; const moving = controls.update(); inLoop = false; renderer.render(scene, cam);
    idle = moving || controls.autoRotate ? 0 : idle + 1;
    if (idle < 30 && !raf) raf = requestAnimationFrame(loop);
  }
  function kick() { if (!raf) raf = requestAnimationFrame(loop); }
  load(seg.querySelector('[aria-pressed=true]').dataset.model);
}

