// Shared look for every three.js view on the page: a procedural studio environment (soft boxes in the
// brand blue / violet, prefiltered with PMREM so metal and clearcoat reflect something), material polish
// for the meshgen .glb files, and a few small canvas textures. No network, no HDR files.
import * as THREE from 'three';

let envCache = null;
export function studioEnv(renderer) {
  if (envCache) return envCache;
  const s = new THREE.Scene();
  s.add(new THREE.Mesh(new THREE.BoxGeometry(14, 14, 14), new THREE.MeshBasicMaterial({ color: 0x05060b, side: THREE.BackSide })));
  const panel = (w, h, hex, k, pos) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({ color: new THREE.Color(hex).multiplyScalar(k), side: THREE.DoubleSide }));
    m.position.set(...pos); m.lookAt(0, 0, 0); s.add(m);
  };
  panel(7, 2.2, 0xffffff, 3.2, [0, 6, .5]);        // overhead soft box
  panel(4.5, 1.4, 0xf2f5ff, 2.2, [1.5, 2.2, 6]);   // front fill strip
  panel(2.2, 6, 0x3d7bff, 4.5, [-6, 1, -2]);       // brand blue rim
  panel(2.2, 6, 0x8b5cff, 3.6, [6, .8, -3]);       // brand violet rim
  panel(6, .6, 0xffffff, 1.4, [0, -1.2, -6]);      // low horizon line for long highlights
  const pm = new THREE.PMREMGenerator(renderer);
  envCache = pm.fromScene(s, .035).texture; pm.dispose();
  return envCache;
}

/** Swap the glTF standard materials for physical ones tuned for the dark page: real metal, a clearcoat on
 *  painted parts, softer plastics, and brand-coloured emissive accents that actually glow. */
export function polish(root, { glow } = {}) {
  root.traverse((o) => {
    if (!o.isMesh) return;
    o.castShadow = true; o.receiveShadow = true;
    const src = o.material; if (!src || !src.isMeshStandardMaterial) return;
    const m = new THREE.MeshPhysicalMaterial({
      color: src.color.clone(), metalness: src.metalness, roughness: src.roughness,
      emissive: src.emissive.clone(), emissiveIntensity: src.emissiveIntensity, map: src.map, normalMap: src.normalMap,
    });
    const em = src.emissive.r + src.emissive.g + src.emissive.b > .05;
    if (em) {
      if (glow) { m.color.set(glow); m.emissive.set(glow); }
      m.emissiveIntensity = 2.6; m.roughness = .25; m.metalness = 0; m.toneMapped = true;
    } else if (m.metalness > .55) {
      m.roughness = Math.min(.42, Math.max(.2, m.roughness * .7)); m.clearcoat = .35; m.clearcoatRoughness = .3;
      // near-black base colours read as holes under ACES; lift them into gunmetal
      const l = m.color.r + m.color.g + m.color.b; if (l < .12) m.color.setRGB(.05, .056, .066);
    } else {
      m.roughness = Math.max(.42, m.roughness); m.clearcoat = .18; m.clearcoatRoughness = .55;
      m.sheen = .25; m.sheenRoughness = .6; m.sheenColor = new THREE.Color(0x3d7bff).multiplyScalar(.25);
    }
    m.envMapIntensity = 1.15; o.material = m;
  });
  return root;
}

/** Vertical page-matching backdrop: deep navy to black with a faint blue floor glow. */
export function backdrop({ top = '#0b0e1b', bottom = '#030408', glow = 'rgba(61,123,255,.16)', gy = .78 } = {}) {
  const c = document.createElement('canvas'); c.width = 8; c.height = 256; const x = c.getContext('2d');
  const g = x.createLinearGradient(0, 0, 0, 256); g.addColorStop(0, top); g.addColorStop(1, bottom); x.fillStyle = g; x.fillRect(0, 0, 8, 256);
  const h = x.createLinearGradient(0, 256 * (gy - .25), 0, 256 * (gy + .2)); h.addColorStop(0, 'rgba(0,0,0,0)'); h.addColorStop(.55, glow); h.addColorStop(1, 'rgba(0,0,0,0)');
  x.fillStyle = h; x.fillRect(0, 0, 8, 256);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

/** Soft radial alpha used to fade floors into the backdrop. */
export function radialAlpha(inner = .15, outer = .5) {
  const c = document.createElement('canvas'); c.width = c.height = 256; const x = c.getContext('2d');
  const g = x.createRadialGradient(128, 128, 256 * inner, 128, 128, 256 * outer); g.addColorStop(0, '#fff'); g.addColorStop(1, '#000');
  x.fillStyle = g; x.fillRect(0, 0, 256, 256); return new THREE.CanvasTexture(c);
}

/** A dark reflective floor that fades out at its edge and takes shadows. */
export function floor(radius = 3, { color = 0x0b0e17, rough = .5, metal = .15, y = 0 } = {}) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(radius, 64), new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal, alphaMap: radialAlpha(.1, .5), transparent: true, depthWrite: false, envMapIntensity: .5 }));
  m.rotation.x = -Math.PI / 2; m.position.y = y; m.receiveShadow = true; m.renderOrder = -1; return m;
}

