// Motion & effects studio: eight real-time loops (three.js), lazy-loaded by main.js.
// ONE WebGL renderer draws every tile in turn and blits it into that tile's own 2D canvas, so the page holds a
// single GL context however many tiles there are, tiles keep their rounded corners, and a paused or offscreen
// tile costs nothing (its 2D canvas keeps the last frame).
// Effects are the Cyrus procedural flipbooks (256 px frames, CC0, generated by Nxeon) played with frame
// blending and proper additive / alpha blending, plus GPU point particles, real lights and real shadows.
import * as THREE from 'three';
import { GLTFLoader } from '../vendor/GLTFLoader.js';
import { studioEnv, polish, backdrop, floor, radialAlpha } from './studio-env.js';

// sheet metadata (frames, grid, authored fps, additive?) copied from the library's flipbook json
const FX = {
  'muzzle-star7': [8, 4, 2, 30, 1], 'muzzle-side-warm': [8, 4, 2, 30, 1], 'smoke-puff-light': [16, 4, 4, 20, 0],
  'explosion-fireball-large': [32, 8, 4, 30, 1], 'explosion-shockwave': [32, 8, 4, 30, 1], 'smoke-plume-dark': [16, 4, 4, 16, 0],
  'sparks-burst-fire': [16, 4, 4, 24, 1], 'fire-inferno': [16, 4, 4, 20, 1], 'embers-rising-fire': [16, 4, 4, 16, 1],
  'smoke-plume-light': [16, 4, 4, 16, 0], 'splash-water': [16, 4, 4, 24, 0], 'ripple-drop-water': [16, 4, 4, 20, 0],
  'magic-ring-blue': [16, 4, 4, 20, 1], 'magic-orb-purple': [16, 4, 4, 20, 1], 'electric-ball-purple': [8, 4, 2, 20, 1], 'dust-puff-grey': [16, 4, 4, 20, 0],
};

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const smooth = (a, b, v) => { const t = clamp((v - a) / (b - a)); return t * t * (3 - 2 * t); };
const easeOut = (t) => 1 - Math.pow(1 - clamp(t), 3);
const easeIn = (t) => Math.pow(clamp(t), 2.2);
// deterministic hash so a tile looks the same every loop and in the reduced-motion still
const rnd = (i, s = 0) => { const x = Math.sin(i * 127.1 + s * 311.7) * 43758.5453; return x - Math.floor(x); };

/* ---------------- flipbook sprite ---------------- */
const FB_VERT = `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.); }`;
const FB_FRAG = `
uniform sampler2D map; uniform vec2 grid; uniform float n, frame, opacity, add, loopIt; uniform vec3 tint; varying vec2 vUv;
vec4 tap(float f){ float c = mod(f, grid.x), r = floor(f / grid.x); return texture2D(map, (vec2(c, grid.y - 1. - r) + vUv) / grid); }
void main(){
  float f0 = floor(frame), t = frame - f0;
  float f1 = loopIt > .5 ? mod(f0 + 1., n) : min(f0 + 1., n - 1.);
  vec4 c = mix(tap(mod(f0, n)), tap(f1), t);           // frame blending: smooth at any playback rate
  // keep the sample inside its cell (no bleed from the neighbour frame at the edge)
  float e = min(min(vUv.x, 1. - vUv.x), min(vUv.y, 1. - vUv.y)); c *= smoothstep(0., .02, e);
  if (add > .5) gl_FragColor = vec4(c.rgb * tint, opacity);
  else gl_FragColor = vec4(c.rgb * tint, c.a * opacity);
  #include <colorspace_fragment>
}`;

class Flip {
  constructor(tex, key, { tint = 0xffffff, opacity = 1, loop = true, fps, flat = false, anchor = 'center' } = {}) {
    const [n, gx, gy, afps, add] = FX[key];
    this.n = n; this.fps = fps ?? afps; this.loop = loop;
    const geo = new THREE.PlaneGeometry(1, 1); if (anchor === 'bottom') geo.translate(0, .5, 0); if (anchor === 'left') geo.translate(.5, 0, 0);
    this.mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: tex }, grid: { value: new THREE.Vector2(gx, gy) }, n: { value: n }, frame: { value: 0 }, opacity: { value: opacity }, add: { value: add }, loopIt: { value: loop ? 1 : 0 }, tint: { value: new THREE.Color(tint) } },
      vertexShader: FB_VERT, fragmentShader: FB_FRAG, transparent: true, depthWrite: false, toneMapped: false,
      blending: add ? THREE.AdditiveBlending : THREE.NormalBlending, side: THREE.DoubleSide,
    });
    this.mesh = new THREE.Mesh(geo, this.mat); this.flat = flat;
    if (flat) this.mesh.rotation.x = -Math.PI / 2;
  }
  /** t in seconds since this sprite started; returns false once a one-shot has finished */
  at(t) {
    const f = t * this.fps;
    if (!this.loop && f >= this.n - 1) { this.mesh.visible = false; return false; }
    this.mesh.visible = t >= 0; this.mat.uniforms.frame.value = this.loop ? f % this.n : Math.max(0, f); return true;
  }
  set opacity(v) { this.mat.uniforms.opacity.value = v; }
  face(cam) { if (!this.flat) this.mesh.quaternion.copy(cam.quaternion); }
}

/* ---------------- GPU point particles (soft, additive) ---------------- */
const PT_VERT = `attribute float aSize; attribute vec4 aCol; varying vec4 vCol; uniform float uScale;
void main(){ vCol = aCol; vec4 mv = modelViewMatrix * vec4(position,1.); gl_PointSize = aSize * uScale / -mv.z; gl_Position = projectionMatrix * mv; }`;
const PT_FRAG = `varying vec4 vCol; void main(){ float d = length(gl_PointCoord - .5); float a = smoothstep(.5, .0, d); a *= a;
  gl_FragColor = vec4(vCol.rgb, vCol.a * a);
  #include <colorspace_fragment>
}`;
class Points {
  constructor(cap) {
    this.cap = cap; this.p = new Float32Array(cap * 3); this.c = new Float32Array(cap * 4); this.s = new Float32Array(cap);
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.p, 3)); g.setAttribute('aCol', new THREE.BufferAttribute(this.c, 4)); g.setAttribute('aSize', new THREE.BufferAttribute(this.s, 1));
    this.mat = new THREE.ShaderMaterial({ uniforms: { uScale: { value: 300 } }, vertexShader: PT_VERT, fragmentShader: PT_FRAG, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false });
    this.obj = new THREE.Points(g, this.mat); this.obj.frustumCulled = false; this.g = g; this.k = 0;
  }
  begin() { this.k = 0; }
  put(x, y, z, r, g, b, a, size) {
    if (this.k >= this.cap) return; const i = this.k++;
    this.p.set([x, y, z], i * 3); this.c.set([r, g, b, a], i * 4); this.s[i] = size;
  }
  end() { for (let i = this.k; i < this.cap; i++) this.c[i * 4 + 3] = 0; for (const a of ['position', 'aCol', 'aSize']) this.g.attributes[a].needsUpdate = true; }
}

/* ---------------- shared helpers ---------------- */
function stage(cam) {
  const scene = new THREE.Scene(); scene.background = backdrop();
  scene.add(new THREE.HemisphereLight(0xcdd8ff, 0x05060a, .35));
  return { scene, cam };
}
function studioLights(scene, { shadow = true, key = 2.4, box = 1.6 } = {}) {
  const k = new THREE.DirectionalLight(0xffffff, key); k.position.set(2.2, 4, 2.8);
  if (shadow) { k.castShadow = true; k.shadow.mapSize.set(1024, 1024); const c = k.shadow.camera; c.left = c.bottom = -box; c.right = c.top = box; c.near = .5; c.far = 12; k.shadow.bias = -.0004; k.shadow.normalBias = .02; k.shadow.radius = 3; }
  scene.add(k);
  const b = new THREE.DirectionalLight(0x3d7bff, 5); b.position.set(-3.5, 1.6, -2.5); scene.add(b);
  const v = new THREE.DirectionalLight(0x8b5cff, 3.6); v.position.set(3.2, 1.1, -3.4); scene.add(v);
  return { k, b, v };
}
function cam(fov, pos, look) { const c = new THREE.PerspectiveCamera(fov, 1, .05, 60); c.position.set(...pos); c.lookAt(...look); c.userData.base = c.position.clone(); c.userData.look = new THREE.Vector3(...look); return c; }
function shake(c, amt, t) { const b = c.userData.base; c.position.set(b.x + Math.sin(t * 93) * amt, b.y + Math.sin(t * 71 + 1) * amt, b.z); c.lookAt(c.userData.look); }
function fitTo(obj, len) {
  const box = new THREE.Box3().setFromObject(obj), size = box.getSize(new THREE.Vector3()), ctr = box.getCenter(new THREE.Vector3());
  const s = len / Math.max(size.x, size.y, size.z); obj.scale.setScalar(s); obj.position.set(-ctr.x * s, -ctr.y * s, -ctr.z * s);
  return { s, h: size.y * s };
}
function woodTexture() {
  const c = document.createElement('canvas'); c.width = 128; c.height = 512; const x = c.getContext('2d');
  x.fillStyle = '#5a3a22'; x.fillRect(0, 0, 128, 512);
  for (let i = 0; i < 140; i++) { const px = rnd(i, 3) * 128, w = .6 + rnd(i, 4) * 2.4; x.strokeStyle = `rgba(${rnd(i, 5) > .5 ? '30,16,8' : '120,82,50'},${.15 + rnd(i, 6) * .35})`; x.lineWidth = w; x.beginPath(); x.moveTo(px, 0); for (let y = 0; y <= 512; y += 32) x.lineTo(px + Math.sin(y * .02 + i) * 3, y); x.stroke(); }
  for (let i = 0; i < 3; i++) { const kx = rnd(i, 9) * 110 + 9, ky = rnd(i, 10) * 480 + 16; const g = x.createRadialGradient(kx, ky, 0, kx, ky, 9); g.addColorStop(0, 'rgba(25,12,5,.8)'); g.addColorStop(1, 'rgba(25,12,5,0)'); x.fillStyle = g; x.fillRect(kx - 10, ky - 10, 20, 20); }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t;
}
function stoneTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 128; const x = c.getContext('2d');
  x.fillStyle = '#3a3d46'; x.fillRect(0, 0, 128, 128);
  for (let i = 0; i < 900; i++) { const v = 40 + rnd(i, 1) * 50 | 0; x.fillStyle = `rgba(${v},${v + 2},${v + 8},.35)`; x.fillRect(rnd(i, 2) * 128, rnd(i, 3) * 128, 1 + rnd(i, 4) * 3, 1 + rnd(i, 5) * 3); }
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; return t;
}

/* ================= tiles ================= */
// each builder gets the shared kit and returns { scene, cam, update(t), hero } (t = seconds since the tile started)

async function tileFire(kit, model = 'rifle_ak', reload = false) {
  const { scene, cam: c } = stage(cam(30, [.15, .42, 2.75], [.05, .02, 0]));
  scene.environment = kit.env; scene.environmentIntensity = .85;
  const L = studioLights(scene);
  const gl = await kit.glb(`assets/models/${model}.glb`);
  const gun = polish(gl.scene.clone(true)); const pivot = new THREE.Group(); const holder = new THREE.Group();
  holder.add(gun); pivot.add(holder); scene.add(pivot);
  const { s, h } = fitTo(gun, 1.75);
  pivot.rotation.y = reload ? -.28 : .3; pivot.rotation.x = reload ? .06 : 0;
  scene.add(floor(2.4, { y: -h / 2 - (reload ? .38 : .14) }));
  // muzzle in model space: the barrel's far end on +X
  const bar = gun.getObjectByName('barrel'); const bb = new THREE.Box3().setFromObject(bar);
  const muzzleL = holder.worldToLocal(new THREE.Vector3(bb.max.x, (bb.min.y + bb.max.y) / 2 - (bb.max.y - bb.min.y) * .22, 0));
  const mag = gun.getObjectByName('magazine');
  // pivot the magazine about the top of its own bounding box so it can rock out of the well
  let magPivot = null;
  if (mag) { const mb = new THREE.Box3().setFromObject(mag); magPivot = new THREE.Group(); magPivot.position.copy(holder.worldToLocal(new THREE.Vector3((mb.min.x + mb.max.x) / 2, mb.max.y, 0))); holder.add(magPivot); magPivot.attach(mag); }

  const pts = new Points(400); scene.add(pts.obj);
  const out = { scene, cam: c, pts };
  if (!reload) {
    const star = new Flip(kit.tex('muzzle-star7'), 'muzzle-star7', { loop: false, fps: 60, tint: 0xffd9a8 });
    const side = new Flip(kit.tex('muzzle-side-warm'), 'muzzle-side-warm', { loop: false, fps: 60, anchor: 'left' });
    star.mesh.scale.setScalar(.42); side.mesh.scale.set(.62, .3, 1); holder.add(side.mesh); scene.add(star.mesh);
    side.mesh.position.copy(muzzleL);
    const puffs = [0, 1, 2].map(() => { const f = new Flip(kit.tex('smoke-puff-light'), 'smoke-puff-light', { loop: false, fps: 14, tint: 0xc9d2e2 }); scene.add(f.mesh); return f; });
    const flash = new THREE.PointLight(0xff9a40, 0, 3.2, 2); scene.add(flash);
    const brass = new THREE.MeshPhysicalMaterial({ color: 0xc9a24a, metalness: 1, roughness: .22, clearcoat: .4 });
    const shells = [0, 1, 2].map(() => { const m = new THREE.Mesh(new THREE.CylinderGeometry(.011, .011, .05, 12), brass); m.castShadow = true; scene.add(m); return m; });
    const SHOTS = [0, .12, .24], P = 1.7, floorY = -h / 2 - .14;
    out.hero = .028;
    out.update = (T) => {
      const t = T % P; const mw = holder.localToWorld(muzzleL.clone());
