      holder.position.x = -.05 * k; holder.rotation.z = .07 * k; holder.position.y = .012 * k;
      const last = SHOTS.filter((s0) => t >= s0).pop(); const d = last === undefined ? 9 : t - last;
      star.at(d); side.at(d); star.mesh.position.copy(mw); star.mesh.rotation.z = rnd(SHOTS.indexOf(last), 1) * 6; star.face(c); star.mesh.rotateZ(rnd(SHOTS.indexOf(last), 2) * 6.28);
      side.mesh.visible = star.mesh.visible;
      flash.position.copy(mw); flash.intensity = d < .09 ? 9 * (1 - d / .09) : 0;
      puffs.forEach((p, i) => { const pd = t - SHOTS[i] - .02; p.at(pd); if (pd < 0) return; p.mesh.position.set(mw.x + .1 + pd * .25, mw.y + .02 + pd * .22, mw.z - pd * .1); p.mesh.scale.setScalar(.22 + pd * .55); p.opacity = .42 * (1 - smooth(.2, 1.1, pd)); p.face(c); });
      // ejected casings: up, back and toward the camera, spinning, one bounce
      shells.forEach((m, i) => {
        const sd = t - SHOTS[i]; if (sd < 0 || sd > 1.2) { m.visible = false; return; }
        m.visible = true; const ej = holder.localToWorld(new THREE.Vector3(.2 / s * s * 0 + .02, .1, .03));
        let y = ej.y + 1.9 * sd - 4.9 * sd * sd, vx = .55 + rnd(i, 3) * .2;
        if (y < floorY + .012) { const tb = (1.9 + Math.sqrt(1.9 * 1.9 + 19.6 * (ej.y - floorY - .012))) / 9.8; const st = sd - tb; y = floorY + .012 + Math.max(0, .5 * st - 4.9 * st * st); }
        m.position.set(ej.x - vx * sd * .6, y, ej.z + sd * .55); m.rotation.set(sd * 22, sd * 9, Math.PI / 2 + sd * 5);
      });
