      pts.begin(); pts.mat.uniforms.uScale.value = kit.scale(c);
      SHOTS.forEach((s0, si) => { const sd = t - s0; if (sd < 0 || sd > .45) return;
        for (let i = 0; i < 26; i++) { const life = .18 + rnd(i, si) * .26; if (sd > life) continue; const sp = 2.2 + rnd(i, si + 7) * 3;
          const a = rnd(i, si + 3) * 6.28, cone = .22 * rnd(i, si + 5);
          const vx = dir.x * sp + Math.cos(a) * cone * sp, vy = dir.y * sp + Math.sin(a) * cone * sp - 2.5 * sd, vz = dir.z * sp + Math.sin(a + 1) * cone * sp;
          const f = 1 - sd / life; pts.put(mw.x + vx * sd, mw.y + vy * sd, mw.z + vz * sd, 1, .62 + .3 * f, .25 * f, f, .028 + .02 * f);
        } });
      pts.end();
      L.k.intensity = 2.4;
    };
  } else {
    // RELOAD: drum out, fresh drum in, seat, then a charging-handle rack
    const P = 3.6; const glint = new THREE.PointLight(0x7aa6ff, 0, 1.4, 2); scene.add(glint);
    out.hero = 1.05;
    out.update = (T) => {
      const t = T % P;
