      if (magPivot) { magPivot.position.y += 0; magPivot.children[0].position.set(0, 0, 0); magPivot.rotation.z = -.5 * off; magPivot.userData.y ??= magPivot.position.y; magPivot.position.y = magPivot.userData.y - .42 * off; magPivot.userData.x ??= magPivot.position.x; magPivot.position.x = magPivot.userData.x - .08 * off; }
      const seat = t - 1.85; const jolt = seat > 0 ? Math.exp(-seat * 14) * Math.sin(seat * 60) : 0;
      const rack = smooth(2.3, 2.5, t) * (1 - smooth(2.62, 2.82, t)); const rk = t - 2.62; const rj = rk > 0 ? Math.exp(-rk * 12) * Math.sin(rk * 50) : 0;
      holder.rotation.z = .1 * smooth(.2, .45, t) * (1 - smooth(1.9, 2.2, t)) + .02 * jolt + .25 * rack + .03 * rj;
