const WATER_FRAG = `
uniform float uTime; uniform vec4 uDrop[3]; uniform vec3 uLight; varying vec3 vW;
void main(){
  vec2 p = vW.xz; float hx = 0., hz = 0.;
  // a slow swell so the surface is never dead flat
  hx += .010 * cos(p.x * 3.1 + uTime * .9) + .006 * cos((p.x + p.y) * 5.3 + uTime * 1.4);
  hz += .010 * cos(p.y * 2.7 - uTime * .7) + .006 * cos((p.x + p.y) * 5.3 + uTime * 1.4);
  for (int i = 0; i < 3; i++) {
    vec2 d = p - uDrop[i].xy; float r = length(d) + 1e-4, age = uTime - uDrop[i].z; if (age < 0. || age > 3.) continue;
    float front = age * .85, x = r - front;
    float env = exp(-x * x * 18.) * exp(-age * 1.1) * smoothstep(0., .08, front) / (1. + r * 3.);
    float dh = cos(x * 34.) * 34. * .010 * env;   // derivative of sin(x*34) along r
    hx += dh * d.x / r; hz += dh * d.y / r;
  }
  vec3 N = normalize(vec3(-hx, 1., -hz)); vec3 V = normalize(cameraPosition - vW); vec3 R = reflect(-V, N);
  float fres = .03 + .97 * pow(1. - max(dot(N, V), 0.), 5.);
  vec3 sky = mix(vec3(.006, .01, .03), vec3(.10, .22, .62), smoothstep(-.05, .5, R.y)) + vec3(.35, .25, .9) * pow(max(R.y, 0.), 6.) * .25;
  float spec = pow(max(dot(R, normalize(uLight)), 0.), 220.) * 6. + pow(max(dot(R, normalize(uLight)), 0.), 24.) * .25;
  vec3 deep = vec3(.004, .018, .04);
  vec3 col = mix(deep, sky, fres) + spec * vec3(.8, .88, 1.);
  float fade = 1. - smoothstep(1.2, 2.6, length(p));
  gl_FragColor = vec4(col, fade);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}`;

