  const { scene, cam: c } = stage(cam(32, [0, 1.25, 4.3], [0, .85, 0]));
  scene.background = backdrop({ top: '#0d0b1d', bottom: '#030308', glow: 'rgba(139,92,255,.2)' });
  scene.environment = kit.env; scene.environmentIntensity = .7;
  scene.add(floor(3, { color: 0x0b0b15, rough: .35, metal: .3 }));
  const obs = new THREE.MeshPhysicalMaterial({ color: 0x0c0c16, metalness: .3, roughness: .18, clearcoat: 1, clearcoatRoughness: .08 });
  const ped = new THREE.Mesh(new THREE.CylinderGeometry(.34, .42, .26, 6), obs); ped.position.y = .13; ped.castShadow = true; scene.add(ped);
  const ringF = new Flip(kit.tex('magic-ring-blue'), 'magic-ring-blue', { fps: 18, flat: true }); ringF.mesh.scale.setScalar(2.3); ringF.mesh.position.y = .012; scene.add(ringF.mesh);
  const orb = new Flip(kit.tex('magic-orb-purple'), 'magic-orb-purple', { fps: 18 }); orb.mesh.scale.setScalar(1.25); scene.add(orb.mesh);
  const arc = new Flip(kit.tex('electric-ball-purple'), 'electric-ball-purple', { fps: 16, tint: 0xc9b4ff }); arc.mesh.scale.setScalar(1.05); arc.opacity = .85; scene.add(arc.mesh);
  const light = new THREE.PointLight(0x8b5cff, 6, 4, 1.5); scene.add(light);
  const blue = new THREE.PointLight(0x3d7bff, 3, 3, 1.5); blue.position.set(0, .15, .5); scene.add(blue);
  const pts = new Points(140); scene.add(pts.obj);
  return {
    scene, cam: c, hero: .7,
    update(T) {
      const y = 1.02 + Math.sin(T * 1.6) * .06;
      ringF.at(T); orb.at(T + 3); arc.at(T); orb.mesh.position.set(0, y, 0); arc.mesh.position.set(0, y, .02); orb.face(c); arc.face(c); arc.mesh.rotateZ(T * .4);
      light.position.set(0, y, .2); light.intensity = 6 + 1.5 * Math.sin(T * 5.1); blue.intensity = 3 + Math.sin(T * 3.2);
      pts.begin(); pts.mat.uniforms.uScale.value = kit.scale(c);
      for (let i = 0; i < 110; i++) { const life = 2 + rnd(i, 1) * 2, u = ((T + rnd(i, 2) * life) % life) / life, a = rnd(i, 3) * 6.28 + T * (.6 + rnd(i, 4) * .6), r = .55 + rnd(i, 5) * .45 - u * .3;
        const v = rnd(i, 6) > .5; pts.put(Math.cos(a) * r, .1 + u * 1.7, Math.sin(a) * r * .8, v ? .62 : .35, v ? .45 : .58, 1, Math.sin(u * Math.PI) * .9, .014 + rnd(i, 7) * .016); }
      pts.end();
    },
  };
}

const BUILDERS = { fire: (k) => tileFire(k), reload: (k) => tileFire(k, 'rifle_drum_lmg', true), door: tileDoor, explosion: tileExplosion, flame: tileFlame, smoke: tileSmoke, water: tileWater, arcane: tileArcane };

/* ================= runner ================= */
export async function initMotion(card, { reduce }) {
  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'low-power' });
  renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.15;
  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  const env = studioEnv(renderer);
  const texL = new THREE.TextureLoader(), texC = {}, glbC = {}, gltf = new GLTFLoader(), pend = [];
  const kit = {
    env,
    tex(key) {
      if (!texC[key]) { const t = texL.load(`assets/motion/fx/${key}.webp`); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; texC[key] = t; pend.push(new Promise((r) => { const chk = () => (t.image && t.image.complete !== false && t.image.width ? r() : setTimeout(chk, 40)); chk(); })); }
      return texC[key];
    },
    glb(url) { return (glbC[url] ??= gltf.loadAsync(url)); },
    scale(c) { return H / (2 * Math.tan(THREE.MathUtils.degToRad(c.fov) / 2)); },
  };
  let W = 1, H = 1, dpr = Math.min(devicePixelRatio || 1, 1.6);
  const tiles = [...card.querySelectorAll('.loop[data-fx]')].map((b) => {
    const spr = b.querySelector('.spr'); const cv = document.createElement('canvas'); cv.className = 'fxc'; cv.setAttribute('aria-hidden', 'true'); spr.append(cv);
    return { b, spr, cv, ctx: cv.getContext('2d'), key: b.dataset.fx, t: 0, vis: false, paused: reduce, ready: false, dirty: true, view: null };
  });
  // build every tile (textures/glbs load in parallel); a tile shows its poster until it is ready
  await Promise.all(tiles.map(async (L) => {
    try { pend.length = 0; L.view = await BUILDERS[L.key](kit); await Promise.all(pend.slice()); }
    catch (e) { console.warn('motion tile failed', L.key, e); L.view = null; }
  }));
  await Promise.all(Object.values(texC).map((t) => new Promise((r) => { const chk = () => (t.image && t.image.width ? r() : setTimeout(chk, 40)); chk(); })));
  for (const L of tiles) if (L.view) { L.t = L.view.hero; L.ready = true; L.dirty = true; renderer.compile(L.view.scene, L.view.cam); }

  function resize() {
    const r = tiles[0].spr.getBoundingClientRect(); dpr = Math.min(devicePixelRatio || 1, 1.6);
    W = Math.max(1, Math.round(r.width * dpr)); H = Math.max(1, Math.round(r.height * dpr));
    renderer.setPixelRatio(1); renderer.setSize(W, H, false);
    for (const L of tiles) { L.cv.width = W; L.cv.height = H; L.dirty = true; if (L.view) { L.view.cam.aspect = W / H; L.view.cam.updateProjectionMatrix(); } }
    kick();
  }
  new ResizeObserver(resize).observe(tiles[0].spr); resize();

  const io = new IntersectionObserver((es) => { for (const e of es) { const L = tiles.find((x) => x.spr === e.target); if (L) { L.vis = e.isIntersecting; if (L.vis) L.dirty = true; } } kick(); }, { rootMargin: '80px' });
  tiles.forEach((L) => io.observe(L.spr));
  document.addEventListener('visibilitychange', kick);

  function draw(L) {
    L.view.update(L.t);
    if (L.view.cam.userData.base && !reduce) { /* shake handled in update */ }
    renderer.render(L.view.scene, L.view.cam);
    L.ctx.drawImage(renderer.domElement, 0, 0, W, H);
    if (!L.shown) { L.shown = true; L.b.classList.add('live'); }
    L.dirty = false;
  }
  let raf = 0, last = 0;
  function frame(now) {
    raf = 0; const dt = Math.min(.05, (now - (last || now)) / 1000); last = now; let again = false;
    if (document.hidden) { last = 0; return; }
    for (const L of tiles) {
      if (!L.ready || !L.vis) continue;
      if (!L.paused) { L.t += dt; again = true; draw(L); } else if (L.dirty) draw(L);
    }
    if (again) raf = requestAnimationFrame(frame); else last = 0;
  }
  function kick() { if (!raf) raf = requestAnimationFrame(frame); }

  return {
    toggle(b) { const L = tiles.find((x) => x.b === b); if (!L || !L.ready) return null; L.paused = !L.paused; L.dirty = true; kick(); return L.paused; },
    paused(b) { const L = tiles.find((x) => x.b === b); return L ? L.paused : true; },
  };
}

