// usage: node landing-shots.cjs <siteDir> <outDir> [mode]
const http = require('http'), fs = require('fs'), path = require('path');
const { chromium } = require('playwright');
const [,, dir, out, mode = 'all'] = process.argv;
fs.mkdirSync(out, { recursive: true });
const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.webp': 'image/webp', '.png': 'image/png', '.svg': 'image/svg+xml', '.glb': 'model/gltf-binary', '.woff2': 'font/woff2', '.json': 'application/json' };
const srv = http.createServer((q, r) => { let p = decodeURIComponent(q.url.split('?')[0]); if (p.endsWith('/')) p += 'index.html'; const f = path.join(dir, p); fs.readFile(f, (e, b) => { if (e) { r.writeHead(404); r.end(); return; } r.writeHead(200, { 'content-type': types[path.extname(f)] || 'application/octet-stream' }); r.end(b); }); });
srv.listen(0, '127.0.0.1', async () => {
  const url = `http://127.0.0.1:${srv.address().port}/`;
  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
  const errs = [];
  async function page(vp, reduced) {
    const ctx = await browser.newContext({ viewport: vp, deviceScaleFactor: vp.width < 500 ? 2 : 1, reducedMotion: reduced ? 'reduce' : 'no-preference' });
    const p = await ctx.newPage(); p.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errs.push(`${vp.width}${reduced ? 'rm' : ''}: ${m.text()}`); }); p.on('pageerror', (e) => errs.push('pageerror ' + e.message));
    await p.goto(url, { waitUntil: 'load' }); return { ctx, p };
  }
  async function waitLive(p, sel, n) { await p.waitForFunction(([s, k]) => document.querySelectorAll(s + ' .loop.live').length >= k, [sel, n], { timeout: 90000 }).catch(() => errs.push('timeout waiting live')); }
  if (mode === 'all' || mode === 'desk') {
    const { ctx, p } = await page({ width: 1440, height: 900 });
    await p.locator('.c-mot').scrollIntoViewIfNeeded(); await waitLive(p, '.c-mot', 8);
    for (const [i, d] of [[1, 600], [2, 700], [3, 900]]) { await p.waitForTimeout(d); await p.locator('.c-mot').screenshot({ path: `${out}/desk-mot-${i}.png` }); }
    await p.locator('.c-3d').scrollIntoViewIfNeeded(); await p.waitForTimeout(4000); await p.locator('.c-3d').screenshot({ path: `${out}/desk-3d-rifle.png` });
    for (const m of ['Katana', 'Crate']) { await p.locator('#modelSeg button', { hasText: m }).click(); await p.waitForTimeout(2500); await p.locator('.c-3d').screenshot({ path: `${out}/desk-3d-${m.toLowerCase()}.png` }); }
    const ov = await p.evaluate(() => document.documentElement.scrollWidth > innerWidth); if (ov) errs.push('desk horizontal overflow');
    await ctx.close();
  }
  if (mode === 'all' || mode === 'rm') {
    const { ctx, p } = await page({ width: 1440, height: 900 }, true);
    await p.locator('.c-mot').scrollIntoViewIfNeeded(); await waitLive(p, '.c-mot', 8); await p.waitForTimeout(800);
    await p.locator('.c-mot').screenshot({ path: `${out}/desk-rm-mot.png` });
    for (const k of ['fire', 'reload', 'door', 'explosion', 'flame', 'smoke', 'water', 'arcane']) await p.locator(`.loop[data-fx=${k}] .spr`).screenshot({ path: `${out}/poster-${k}.png` });
    await ctx.close();
  }
  if (mode === 'all' || mode === 'phone') {
    const { ctx, p } = await page({ width: 390, height: 844 });
    await p.locator('.c-mot').scrollIntoViewIfNeeded(); await waitLive(p, '.c-mot', 4); await p.waitForTimeout(1500);
    await p.locator('.c-mot').screenshot({ path: `${out}/phone-mot.png` });
    const ov = await p.evaluate(() => document.documentElement.scrollWidth > innerWidth); if (ov) errs.push('phone horizontal overflow');
    await ctx.close();
  }
  console.log(JSON.stringify({ errs }, null, 1));
  await browser.close(); srv.close();
});
EOF
