import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { installBuildToServer } from "@/lib/modbuilder/install";
import { installPlansFor } from "@/lib/cyrus/lifecycle/server";
import { confirmPlan } from "@/lib/cyrus/lifecycle/install-plan";
import { gamePower } from "@/lib/actions-game-control";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND, ownedBuild } from "../../../_lib";
import { capabilityGate } from "@/lib/cyrus/capabilities";
import { getSettingBool } from "@/lib/settings";

export const dynamic = "force-dynamic";

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as { serverId?: string; restart?: boolean; acceptCapabilities?: string };
  const serverId = String(body.serverId || "");
  if (!serverId) return NextResponse.json({ error: "Pick a server." }, { status: 400 });
  const rl = checkRateLimit(`mb:install:${o.user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: `Too many requests. Retry in ${rl.retryAfterSec}s.` }, { status: 429 });

  // Networking mods: platform switch on + explicit consent bound to the manifest hash.
  const gate = capabilityGate({
    capabilities: (o.build.result as { capabilities?: unknown } | null)?.capabilities ?? null,
    networkingEnabled: await getSettingBool("cyrus_mod_networking_enabled"),
    acceptedSha256: typeof body.acceptCapabilities === "string" ? body.acceptCapabilities : null,
  });
  if (!gate.ok) return NextResponse.json({ error: gate.error, code: gate.code }, { status: gate.status });
  // Cyrus lifecycle: the same install plan the dialog showed: blockers refuse, every warning
  // (version mismatch, legacy version, safety notes) must be acknowledged in `acked`.
  const acked = Array.isArray((body as { acked?: unknown }).acked) ? ((body as { acked: unknown[] }).acked.filter((a) => typeof a === "string") as string[]).slice(0, 20) : [];
  const sp = (await installPlansFor(o.build, o.user.id)).plans.find((p) => p.server.id === serverId);
  if (sp) {
    const c = confirmPlan(sp.plan, acked);
    if (!c.ok) return NextResponse.json({ error: c.error, plan: sp.plan }, { status: 409 });
  }

  const r = await installBuildToServer(o.build, o.user.id, serverId);
  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });

  let restarted = false;
  let restartNote: string | null = null;
  if (body.restart && r.queued) {
    restartNote = "The install is still queued on the server. Restart from the Mods tab once it shows as installed.";
  } else if (body.restart) {
    const p = await gamePower(serverId, "restart");
    restarted = p.ok;
    if (!p.ok) restartNote = p.error;
  }
  const lastInstall = { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted };
  await db.modBuild.update({ where: { id: o.build.id }, data: { lastInstall } });
  await db.auditLog.create({ data: { userId: o.user.id, action: "modbuilder.install", detail: `${o.build.id} -> ${serverId} ${r.path}${r.replaced.length ? ` (replaced ${r.replaced.join(", ")}, backup ${r.backupDir})` : ""}` } }).catch(() => {});
  // modId/queued (additive): the Mods tab lists this install under Installed (Cyrus badge).
  return NextResponse.json({ ok: true, path: r.path, replaced: r.replaced, backupDir: r.backupDir, restarted, restartNote, queued: r.queued, modId: r.modId });
}
