// Cyrus notification preferences (r39). One preference centre for the events of plan 3.4. Storing a preference does
// not send anything: the shared notification system is not built yet (docs say so); senders must read prefsFor().
// Legal / safety notices (takedowns) are always on: they are not marketing and a customer cannot opt out of them.
export const NOTIFY_EVENTS = [
  { id: "build_finished", label: "A build finished", hint: "Success or failure, with the Test Flight result.", email: true, inApp: true, locked: false },
  { id: "install_result", label: "An install finished", hint: "Installed, failed or rolled back on one of your servers.", email: true, inApp: true, locked: false },
  { id: "mod_outdated", label: "A mod needs an update", hint: "Your server moved to a game version the mod was not built for.", email: true, inApp: true, locked: false },
  { id: "tokens_low", label: "Tokens are running low", hint: "Below the low-balance line of your plan.", email: false, inApp: true, locked: false },
  { id: "library", label: "Library contributions", hint: "One of your uploads was published, held or removed.", email: false, inApp: true, locked: false },
  { id: "takedown", label: "Takedowns and safety notices", hint: "Required: we must tell you when content is removed.", email: true, inApp: true, locked: true },
  { id: "product_news", label: "Product news", hint: "Occasional customer-facing changes. Off unless you turn it on.", email: false, inApp: false, locked: false },
] as const;
export type NotifyEvent = (typeof NOTIFY_EVENTS)[number]["id"];
export type Channel = "email" | "inApp";
export type Prefs = Record<NotifyEvent, { email: boolean; inApp: boolean }>;

export function defaultPrefs(): Prefs {
  const p = {} as Prefs;
  for (const e of NOTIFY_EVENTS) p[e.id] = { email: e.email, inApp: e.inApp };
  return p;
}

/** Stored JSON -> full prefs (unknown keys dropped, missing ones defaulted, locked ones forced on). */
export function readPrefs(raw: unknown): Prefs {
  const p = defaultPrefs();
  const r = raw && typeof raw === "object" && !Array.isArray(raw) ? (raw as Record<string, unknown>) : {};
  for (const e of NOTIFY_EVENTS) {
    const v = r[e.id];
    if (e.locked || !v || typeof v !== "object") continue;
    const o = v as Record<string, unknown>;
    if (typeof o.email === "boolean") p[e.id].email = o.email;
    if (typeof o.inApp === "boolean") p[e.id].inApp = o.inApp;
  }
  return p;
}

/** A submitted form (checkbox names "<event>.<channel>") -> prefs. Unchecked = off. */
export function prefsFromForm(fields: Iterable<[string, unknown]>): Prefs {
  const on = new Set<string>();
  for (const [k] of fields) on.add(k);
  const p = defaultPrefs();
  for (const e of NOTIFY_EVENTS) {
    if (e.locked) continue;
    p[e.id] = { email: on.has(`${e.id}.email`), inApp: on.has(`${e.id}.inApp`) };
  }
  return p;
}

export const wants = (p: Prefs, ev: NotifyEvent, ch: Channel) => p[ev][ch];

