// Connected servers + grants (plan 3.3), behind an interface. The Nxeon side (consent screen, scoped primitives,
// audit, webhooks) is NOT built yet, so the default provider is `unavailableGrants`: the UI shows the contract (what
// Cyrus would be allowed to do, per server) and offers nothing it cannot do. When Nxeon exposes the grants API, add a
// provider here and select it in grantsProvider(); the screens do not change.
export const GRANT_SCOPES = [
  { id: "servers.read", label: "See the server", detail: "Name, game, version and loader, status, RAM and CPU, player count." },
  { id: "inventory.read", label: "See installed plugins and mods", detail: "Names and versions, so Cyrus can check conflicts before every build or install." },
  { id: "files.write.mods", label: "Write mods and config", detail: "Only the plugins, mods, config, data pack and resource pack folders, and only over the exact file it expects (hash checked)." },
  { id: "server.reload", label: "Reload the server", detail: "Within a daily budget, after an install." },
  { id: "server.restart", label: "Restart the server", detail: "Within a daily budget, when an install needs it." },
  { id: "logs.read.tail", label: "Read recent logs", detail: "The tail of the console, for Server Doctor and post-install checks." },
  { id: "pack.set", label: "Set the resource pack", detail: "The resource-pack URL and hash in server.properties." },
] as const;
export type GrantScope = (typeof GRANT_SCOPES)[number]["id"];

export type ServerGrant = { serverId: string; scopes: GrantScope[]; grantedAt: string; lastUsedAt: string | null };
export type GrantsState =
  | { available: false; reason: string }
  | { available: true; grants: ServerGrant[]; connectUrl: (serverId: string) => string };

export interface GrantsProvider {
  state(userId: string): Promise<GrantsState>;
  /** Revoke every scope Cyrus holds on this server. Only the owner's own grant; false if there was none. */
  revoke(userId: string, serverId: string): Promise<boolean>;
}

export const unavailableGrants: GrantsProvider = {
  async state() { return { available: false, reason: "Connecting servers to Cyrus is not switched on yet. Installs from the studio still work on your Nxeon servers as they do today." }; },
  async revoke() { return false; },
};

/** In-memory provider (tests). */
export function memoryGrants(seed: (ServerGrant & { userId: string })[] = [], base = "https://nxeon.example"): GrantsProvider & { rows: (ServerGrant & { userId: string })[] } {
  const rows = [...seed];
  return {
    rows,
    async state(userId) { return { available: true, grants: rows.filter((r) => r.userId === userId).map(({ userId: _u, ...g }) => g), connectUrl: (id) => `${base}/dashboard/servers/${encodeURIComponent(id)}/connect-cyrus` }; },
    async revoke(userId, serverId) { const i = rows.findIndex((r) => r.userId === userId && r.serverId === serverId); if (i < 0) return false; rows.splice(i, 1); return true; },
  };
}

let current: GrantsProvider = unavailableGrants;
export const grantsProvider = (): GrantsProvider => current;
export function setGrantsProvider(p: GrantsProvider): () => void { const prev = current; current = p; return () => { current = prev; }; }

