// Data export / deletion requests (r39). A request is recorded; staff handle it (docs: "Cyrus customer app").
// Rules: one open request per kind; a deletion needs the typed confirmation; Cyrus data only (the Nxeon account,
// invoices and servers are Nxeon's and have their own process).
export const DATA_KINDS = ["export", "delete"] as const;
export type DataKind = (typeof DATA_KINDS)[number];
export const OPEN_STATUSES = ["requested", "in_progress"] as const;
export type DataRequestRow = { id: string; userId: string; kind: string; status: string; note: string | null; createdAt: Date; completedAt: Date | null };

export interface DataRequestStore {
  listForUser(userId: string): Promise<DataRequestRow[]>;
  insert(r: { userId: string; kind: DataKind; note: string | null }): Promise<DataRequestRow>;
  cancel(userId: string, id: string): Promise<boolean>;
}

export const DELETE_CONFIRM = "delete my cyrus data";

export async function requestData(store: DataRequestStore, userId: string, input: { kind: unknown; confirm?: unknown; note?: unknown }):
  Promise<{ ok: true; row: DataRequestRow } | { ok: false; error: string }> {
  const kind = String(input.kind ?? "");
  if (!(DATA_KINDS as readonly string[]).includes(kind)) return { ok: false, error: "Unknown request." };
  if (kind === "delete" && String(input.confirm ?? "").trim().toLowerCase() !== DELETE_CONFIRM) return { ok: false, error: `Type "${DELETE_CONFIRM}" to confirm.` };
  const open = (await store.listForUser(userId)).find((r) => r.kind === kind && (OPEN_STATUSES as readonly string[]).includes(r.status));
  if (open) return { ok: false, error: kind === "export" ? "An export is already on its way." : "A deletion request is already open." };
  const note = String(input.note ?? "").replace(/[\u0000-\u001f\u007f]/g, " ").trim().slice(0, 500) || null;
  return { ok: true, row: await store.insert({ userId, kind: kind as DataKind, note }) };
}

export function memoryDataStore(): DataRequestStore & { rows: DataRequestRow[] } {
  const rows: DataRequestRow[] = []; let n = 0;
  return {
    rows,
    async listForUser(u) { return rows.filter((r) => r.userId === u); },
    async insert(r) { const row: DataRequestRow = { ...r, id: `d${++n}`, status: "requested", createdAt: new Date(), completedAt: null }; rows.push(row); return row; },
    async cancel(u, id) { const r = rows.find((x) => x.id === id && x.userId === u && x.status === "requested"); if (!r) return false; r.status = "cancelled"; return true; },
  };
}

