// Customer-app view models (r39). PURE: takes rows the pages already loaded, returns what the screens show.
// Nothing here invents a number: counts come from the rows, a missing value stays missing.
import type { ModBuildView } from "../builder/types";
import { groupProjects, type CyrusProject } from "../projects";
import { readCyrusMeta } from "../meta";

export type FlightBadge = { tone: "ok" | "bad" | "warn" | "wait" | "none"; label: string; detail: string | null };

/** The Test Flight record a build carries (written by the gate worker), as a badge. Never "passed" without a done
 *  flight with a passed verdict. */
export function flightBadge(b: Pick<ModBuildView, "status" | "cyrus">): FlightBadge {
  if (b.status !== "succeeded") return { tone: "none", label: "No Test Flight", detail: "Only finished builds fly." };
  const f = readCyrusMeta(b.cyrus).testFlight as Record<string, unknown> | undefined;
  if (!f) return { tone: "none", label: "Not flown", detail: "No Test Flight on record for this build." };
  const state = String(f.state ?? ""), verdict = String(f.verdict ?? ""), label = typeof f.label === "string" ? f.label : null;
  const reason = typeof f.reason === "string" ? f.reason : null;
  if (state === "queued") return { tone: "wait", label: "Test Flight queued", detail: null };
  if (state === "running") return { tone: "wait", label: "Test Flight running", detail: null };
  if (state === "done" && verdict === "passed") return { tone: "ok", label: label || "Test Flight passed", detail: typeof f.version === "string" ? `Booted on ${f.version}` : null };
  if (state === "done" && verdict === "failed") return { tone: "bad", label: label || "Test Flight failed", detail: reason };
  if (state === "done") return { tone: "warn", label: label || "Test Flight incomplete", detail: reason };
  return { tone: "warn", label: "Test Flight not run", detail: reason };
}

export type BuildRow = { id: string; status: ModBuildView["status"]; label: string; version: string | null; mcVersion: string; createdAt: string; finishedAt: string | null; error: string | null; flight: FlightBadge; head: boolean; installedOn: string | null };
export type ProjectCard = { rootId: string; title: string; updatedAt: string; builds: number; head: { id: string; version: string | null; mcVersion: string } | null; running: boolean; flight: FlightBadge | null; favourite: boolean; lastInstall: { serverName: string; at: string } | null };

export function projectCards(builds: ModBuildView[]): ProjectCard[] {
  return groupProjects(builds).map((p) => ({
    rootId: p.rootId, title: p.title, updatedAt: p.updatedAt, builds: p.builds.length,
    head: p.head ? { id: p.head.id, version: p.head.version, mcVersion: p.head.mcVersion } : null,
    running: !!p.running, flight: p.head ? flightBadge(p.head) : null, favourite: !!p.meta.favourite,
    lastInstall: latestInstall(p),
  })).sort((a, b) => Number(b.favourite) - Number(a.favourite) || b.updatedAt.localeCompare(a.updatedAt));
}

function latestInstall(p: CyrusProject): { serverName: string; at: string } | null {
  let best: { serverName: string; at: string } | null = null;
  for (const b of p.builds) if (b.lastInstall && (!best || b.lastInstall.at > best.at)) best = { serverName: b.lastInstall.serverName, at: b.lastInstall.at };
  return best;
}

export function buildRows(p: CyrusProject): BuildRow[] {
  return [...p.builds].reverse().map((b, i, all) => ({
    id: b.id, status: b.status, mcVersion: b.mcVersion, version: b.version, createdAt: b.createdAt, finishedAt: b.finishedAt, error: b.error,
    label: b.changeRequest ? clip(b.changeRequest, 90) : i === all.length - 1 ? "First build" : clip(b.prompt, 90),
    flight: flightBadge(b), head: p.head?.id === b.id, installedOn: b.lastInstall?.serverName ?? null,
  }));
}

export const clip = (s: string, n: number) => { const t = s.replace(/\s+/g, " ").trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + "…" : t; };

export type ActivityItem = { at: string; kind: "build" | "install" | "tokens" | "library"; text: string; href: string | null; tone: "ok" | "bad" | "neutral" };

/** Merge the recent events the account already has into one feed, newest first. */
export function activityFeed(a: {
  builds: ModBuildView[];
  ledger: { createdAt: Date; delta: number; label: string }[];
  contributions: { createdAt: Date; title: string; status: string }[];
  projectHref: (rootId: string) => string;
}, limit = 12): ActivityItem[] {
  const out: ActivityItem[] = [];
  const titles = new Map(groupProjects(a.builds).map((p) => [p.rootId, p.title]));
  for (const b of a.builds) {
    const root = b.rootBuildId || b.id, t = titles.get(root) ?? "a mod";
    if (b.status === "succeeded") out.push({ at: b.finishedAt || b.createdAt, kind: "build", text: `Built ${t}${b.version ? ` ${b.version}` : ""}`, href: a.projectHref(root), tone: "ok" });
    else if (b.status === "failed") out.push({ at: b.finishedAt || b.createdAt, kind: "build", text: `Build of ${t} failed`, href: a.projectHref(root), tone: "bad" });
    else if (b.status !== "cancelled") out.push({ at: b.createdAt, kind: "build", text: `Building ${t}`, href: a.projectHref(root), tone: "neutral" });
    if (b.lastInstall) out.push({ at: b.lastInstall.at, kind: "install", text: `Installed ${t} on ${b.lastInstall.serverName}`, href: a.projectHref(root), tone: "ok" });
  }
  for (const l of a.ledger) out.push({ at: l.createdAt.toISOString(), kind: "tokens", text: `${l.delta > 0 ? "+" : ""}${l.delta.toLocaleString("en-US")} tokens · ${l.label}`, href: null, tone: "neutral" });
  for (const c of a.contributions) out.push({ at: c.createdAt.toISOString(), kind: "library", text: `Library: ${c.title} (${c.status.replace("-", " ")})`, href: null, tone: c.status === "published" ? "ok" : c.status === "removed" ? "bad" : "neutral" });
  return out.sort((x, y) => y.at.localeCompare(x.at)).slice(0, limit);
}

export type ContributionCounts = { published: number; held: number; pending: number; removed: number; total: number };
export function contributionCounts(rows: { status: string }[]): ContributionCounts {
  const c = { published: 0, held: 0, pending: 0, removed: 0, total: rows.length };
  for (const r of rows) { if (r.status === "published") c.published++; else if (r.status === "held") c.held++; else if (r.status === "removed") c.removed++; else c.pending++; }
  return c;
}

/** "3 min ago" style relative time against `now` (server-rendered, so it is stable per request). */
export function ago(iso: string | null | undefined, now = new Date()): string {
  if (!iso) return "";
  const s = Math.max(0, (now.getTime() - new Date(iso).getTime()) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)} min ago`;
  if (s < 86400) return `${Math.floor(s / 3600)} h ago`;
  if (s < 86400 * 30) return `${Math.floor(s / 86400)} d ago`;
  return new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
}

