// Prisma-backed stores for the customer app (r39), through the Cyrus db door (host seam). SERVER ONLY.
import { cyrusDb } from "../db";
import type { ApiKeyStore } from "./apikeys";
import type { DataRequestStore } from "./data-requests";
import { readPrefs, type Prefs } from "./prefs";

export const prismaKeyStore: ApiKeyStore = {
  listForUser: (userId) => cyrusDb.cyrusPersonalApiKey.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 100 }),
  insert: (r) => cyrusDb.cyrusPersonalApiKey.create({ data: r }),
  async revoke(userId, id, at) { const n = await cyrusDb.cyrusPersonalApiKey.updateMany({ where: { id, userId, revokedAt: null }, data: { revokedAt: at } }); return n.count > 0; },
  bySha: (sha256) => cyrusDb.cyrusPersonalApiKey.findUnique({ where: { sha256 } }),
  async touch(id, at) { await cyrusDb.cyrusPersonalApiKey.update({ where: { id }, data: { lastUsedAt: at } }); },
};

export const prismaDataStore: DataRequestStore = {
  listForUser: (userId) => cyrusDb.cyrusDataRequest.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 50 }),
  insert: (r) => cyrusDb.cyrusDataRequest.create({ data: r }),
  async cancel(userId, id) { const n = await cyrusDb.cyrusDataRequest.updateMany({ where: { id, userId, status: "requested" }, data: { status: "cancelled" } }); return n.count > 0; },
};

export async function loadPrefs(userId: string): Promise<Prefs> {
  const row = await cyrusDb.cyrusNotificationPref.findUnique({ where: { userId } });
  return readPrefs(row?.prefs ?? null);
}
export async function savePrefs(userId: string, prefs: Prefs): Promise<void> {
  const json = JSON.parse(JSON.stringify(prefs));
  await cyrusDb.cyrusNotificationPref.upsert({ where: { userId }, create: { userId, prefs: json }, update: { prefs: json } });
}

