/* Cyrus customer app (r39): the landing's language (black and white, crisp type, electric blue + violet energy,
   glass panels) for every customer page. Everything is scoped to .cx-app and prefixed cx- (no Tailwind collisions).
   Dark is the default; html[data-theme="light"] (the portal toggle) gets a real light theme. */
.cx-app {
  --cx-bg: #000; --cx-bg-2: #06070c; --cx-ink: #fff; --cx-ink-2: rgba(255,255,255,.74); --cx-ink-3: rgba(255,255,255,.56); --cx-ink-4: rgba(255,255,255,.36);
  --cx-line: rgba(255,255,255,.09); --cx-line-2: rgba(255,255,255,.16);
  --cx-blue: #3d7bff; --cx-blue-hi: #79a6ff; --cx-violet: #8b5cff; --cx-violet-hi: #b49bff;
  --cx-ok: #4ade9a; --cx-bad: #ff6b81; --cx-warn: #ffc56b;
  --cx-glass: linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.015)); --cx-glass-2: rgba(255,255,255,.06);
  --cx-energy: linear-gradient(100deg, var(--cx-blue), var(--cx-violet));
  --cx-display: var(--font-space), "Space Grotesk", var(--font-inter), system-ui, sans-serif;
  --cx-body: var(--font-inter), Inter, system-ui, sans-serif; --cx-mono: var(--font-jb), ui-monospace, monospace;
  --cx-r: 18px; --cx-r-sm: 12px;
  color-scheme: dark; background: var(--cx-bg); color: var(--cx-ink); font: 14.5px/1.55 var(--cx-body); -webkit-font-smoothing: antialiased;
  min-height: 100%; position: relative; isolation: isolate;
}
html[data-theme="light"] .cx-app {
  --cx-bg: #f6f7fb; --cx-bg-2: #ffffff; --cx-ink: #07080d; --cx-ink-2: rgba(7,8,13,.76); --cx-ink-3: rgba(7,8,13,.58); --cx-ink-4: rgba(7,8,13,.4);
  --cx-line: rgba(7,8,13,.09); --cx-line-2: rgba(7,8,13,.16); --cx-blue: #2459e0; --cx-blue-hi: #2459e0; --cx-violet: #6a3df0; --cx-violet-hi: #6a3df0;
  --cx-ok: #12865a; --cx-bad: #c8243f; --cx-warn: #9a5b00;
  --cx-glass: linear-gradient(180deg, #fff, #fbfbfe); --cx-glass-2: rgba(7,8,13,.04); color-scheme: light;
}
.cx-app *, .cx-app *::before, .cx-app *::after { box-sizing: border-box; }
.cx-app a { color: inherit; text-decoration: none; }
.cx-app :focus-visible { outline: 2px solid var(--cx-blue-hi); outline-offset: 3px; border-radius: 8px; }
.cx-app ::selection { background: var(--cx-violet); color: #fff; }

/* ambient energy behind the content (no motion when reduced) */
.cx-aura { position: absolute; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
.cx-aura::before, .cx-aura::after { content: ""; position: absolute; width: 60vmax; height: 60vmax; border-radius: 50%; filter: blur(80px); opacity: .16; animation: cx-drift 26s ease-in-out infinite alternate; }
.cx-aura::before { background: radial-gradient(circle, var(--cx-blue), transparent 62%); top: -30vmax; right: -14vmax; }
.cx-aura::after { background: radial-gradient(circle, var(--cx-violet), transparent 62%); bottom: -36vmax; left: -18vmax; animation-delay: -9s; }
html[data-theme="light"] .cx-app .cx-aura::before, html[data-theme="light"] .cx-app .cx-aura::after { opacity: .07; }
@keyframes cx-drift { to { transform: translate3d(4vmax, 3vmax, 0) scale(1.08); } }

/* ---------- shell ---------- */
.cx-shell { display: grid; grid-template-columns: 232px minmax(0, 1fr); min-height: 100%; }
.cx-rail { position: sticky; top: 0; align-self: start; height: 100dvh; max-height: 100%; display: flex; flex-direction: column; gap: 4px; padding: 20px 14px; border-right: 1px solid var(--cx-line); background: color-mix(in srgb, var(--cx-bg) 70%, transparent); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); }
.cx-brand { display: flex; align-items: center; gap: 10px; padding: 4px 10px 18px; }
.cx-brand small { font: 500 10px var(--cx-mono); letter-spacing: .18em; text-transform: uppercase; color: var(--cx-ink-4); }
.cx-nav-a { display: flex; align-items: center; gap: 11px; padding: 9px 11px; border-radius: 11px; color: var(--cx-ink-3); font-weight: 500; transition: background .2s, color .2s; position: relative; }
.cx-nav-a svg { width: 17px; height: 17px; flex: none; }
.cx-nav-a:hover { color: var(--cx-ink); background: var(--cx-glass-2); }
.cx-nav-a[aria-current="page"] { color: var(--cx-ink); background: var(--cx-glass-2); box-shadow: inset 0 0 0 1px var(--cx-line-2); }
.cx-nav-a[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 2px; border-radius: 2px; background: var(--cx-energy); }
.cx-nav-sep { height: 1px; background: var(--cx-line); margin: 10px 8px; }
.cx-rail-foot { margin-top: auto; display: grid; gap: 10px; padding: 10px; border-top: 1px solid var(--cx-line); }
.cx-rail-foot .cx-who { font-size: 12.5px; color: var(--cx-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cx-main { min-width: 0; padding: 28px clamp(16px, 3.4vw, 44px) 64px; }
.cx-page { max-width: 1180px; margin: 0 auto; }

/* ---------- type ---------- */
.cx-eyebrow { font: 500 10.5px var(--cx-mono); letter-spacing: .2em; text-transform: uppercase; color: var(--cx-ink-4); }
.cx-h1 { font: 600 clamp(26px, 3.2vw, 36px)/1.08 var(--cx-display); letter-spacing: -.02em; margin: 6px 0 0; }
.cx-h2 { font: 600 17px/1.2 var(--cx-display); letter-spacing: -.01em; margin: 0; }
.cx-sub { color: var(--cx-ink-3); margin: 8px 0 0; max-width: 64ch; }
.cx-mono { font-family: var(--cx-mono); font-size: 12px; letter-spacing: .02em; }
.cx-muted { color: var(--cx-ink-3); }
.cx-faint { color: var(--cx-ink-4); }
.cx-grad { background: var(--cx-energy); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cx-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }

/* ---------- glass cards ---------- */
.cx-card { position: relative; border-radius: var(--cx-r); background: var(--cx-glass); border: 1px solid var(--cx-line); padding: 18px; overflow: hidden; }
html[data-theme="light"] .cx-app .cx-card { box-shadow: 0 1px 0 rgba(7,8,13,.03), 0 8px 24px -16px rgba(7,8,13,.18); }
.cx-card-h { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.cx-card-h .cx-aside { margin-left: auto; font: 500 11px var(--cx-mono); color: var(--cx-ink-4); }
.cx-glyph { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); flex: none; }
.cx-glyph svg { width: 16px; height: 16px; }
.cx-grid { display: grid; gap: 14px; grid-template-columns: repeat(12, minmax(0, 1fr)); }
.cx-s4 { grid-column: span 4; } .cx-s5 { grid-column: span 5; } .cx-s6 { grid-column: span 6; } .cx-s7 { grid-column: span 7; } .cx-s8 { grid-column: span 8; } .cx-s12 { grid-column: span 12; }
.cx-reveal { animation: cx-in .5s cubic-bezier(.2,.8,.2,1) both; animation-delay: var(--d, 0s); }
@keyframes cx-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- controls ---------- */
.cx-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 38px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--cx-line-2); background: transparent; color: var(--cx-ink); font: 600 13.5px var(--cx-body); cursor: pointer; transition: background .2s, border-color .2s, transform .2s, opacity .2s; white-space: nowrap; }
.cx-btn:hover { background: var(--cx-glass-2); border-color: var(--cx-ink-4); }
.cx-btn:active { transform: translateY(1px); }
.cx-btn[disabled], .cx-btn[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.cx-btn-pri { background: var(--cx-ink); color: var(--cx-bg); border-color: transparent; }
.cx-btn-pri:hover { background: var(--cx-ink); opacity: .9; }
.cx-btn-energy { background: var(--cx-energy); color: #fff; border-color: transparent; box-shadow: 0 8px 28px -10px rgba(110,100,255,.7); }
.cx-btn-energy:hover { opacity: .92; background: var(--cx-energy); }
.cx-btn-danger { color: var(--cx-bad); border-color: color-mix(in srgb, var(--cx-bad) 40%, transparent); }
.cx-btn-sm { height: 30px; padding: 0 12px; font-size: 12.5px; }
.cx-input, .cx-select, .cx-textarea { width: 100%; height: 40px; border-radius: 12px; border: 1px solid var(--cx-line-2); background: var(--cx-bg-2); color: var(--cx-ink); padding: 0 12px; font: 14px var(--cx-body); transition: border-color .2s, box-shadow .2s; }
.cx-textarea { height: auto; min-height: 120px; padding: 12px; line-height: 1.55; resize: vertical; }
.cx-input:focus, .cx-select:focus, .cx-textarea:focus { outline: none; border-color: var(--cx-blue); box-shadow: 0 0 0 3px color-mix(in srgb, var(--cx-blue) 25%, transparent); }
.cx-label { display: grid; gap: 6px; font-size: 12.5px; color: var(--cx-ink-3); font-weight: 500; }
.cx-check { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13.5px; color: var(--cx-ink-2); }
.cx-check input { width: 16px; height: 16px; accent-color: var(--cx-blue); }
.cx-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 999px; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); flex-wrap: wrap; }
.cx-seg a, .cx-seg button { height: 30px; padding: 0 13px; border-radius: 999px; display: inline-flex; align-items: center; font-size: 13px; color: var(--cx-ink-3); background: none; border: 0; cursor: pointer; }
.cx-seg [aria-current="page"], .cx-seg [aria-pressed="true"] { background: var(--cx-ink); color: var(--cx-bg); font-weight: 600; }

/* ---------- data bits ---------- */
.cx-pill { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 999px; font: 500 11px var(--cx-mono); letter-spacing: .02em; border: 1px solid var(--cx-line-2); color: var(--cx-ink-3); white-space: nowrap; }
.cx-pill::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .9; }
.cx-pill.cx-ok { color: var(--cx-ok); border-color: color-mix(in srgb, var(--cx-ok) 35%, transparent); }
.cx-pill.cx-bad { color: var(--cx-bad); border-color: color-mix(in srgb, var(--cx-bad) 35%, transparent); }
.cx-pill.cx-warn { color: var(--cx-warn); border-color: color-mix(in srgb, var(--cx-warn) 35%, transparent); }
.cx-pill.cx-wait { color: var(--cx-blue-hi); border-color: color-mix(in srgb, var(--cx-blue) 40%, transparent); }
.cx-pill.cx-wait::before { animation: cx-pulse 1.4s ease-in-out infinite; }
.cx-pill.cx-none::before { display: none; }
@keyframes cx-pulse { 50% { opacity: .25; } }
.cx-stat { display: grid; gap: 2px; }
.cx-stat b { font: 600 28px/1.05 var(--cx-display); letter-spacing: -.02em; }
.cx-stat span { font-size: 12px; color: var(--cx-ink-3); }
.cx-meter { height: 6px; border-radius: 999px; background: var(--cx-glass-2); overflow: hidden; }
.cx-meter > i { display: block; height: 100%; border-radius: inherit; background: var(--cx-energy); }
.cx-list { display: grid; }
.cx-row { display: flex; align-items: center; gap: 12px; padding: 11px 2px; border-top: 1px solid var(--cx-line); min-width: 0; }
.cx-row:first-child { border-top: 0; }
.cx-row .cx-grow { flex: 1; min-width: 0; }
.cx-row .cx-t { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cx-row .cx-d { font-size: 12.5px; color: var(--cx-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
a.cx-row { border-radius: 10px; transition: background .2s; padding-left: 8px; padding-right: 8px; margin: 0 -8px; }
a.cx-row:hover { background: var(--cx-glass-2); }
.cx-empty { display: grid; place-items: center; text-align: center; gap: 10px; padding: 26px 12px; color: var(--cx-ink-3); }
.cx-tile { width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center; font: 600 12px var(--cx-mono); background: var(--cx-glass-2); border: 1px solid var(--cx-line-2); flex: none; }
.cx-tile.cx-energy { background: var(--cx-energy); color: #fff; border: 0; }
.cx-note { border-radius: 12px; border: 1px dashed var(--cx-line-2); padding: 11px 13px; font-size: 13px; color: var(--cx-ink-3); }
.cx-note b { color: var(--cx-ink-2); }
.cx-error { color: var(--cx-bad); font-size: 13px; }
.cx-okmsg { color: var(--cx-ok); font-size: 13px; }
.cx-code { font: 12.5px var(--cx-mono); background: var(--cx-bg-2); border: 1px solid var(--cx-line-2); border-radius: 10px; padding: 10px 12px; word-break: break-all; user-select: all; }
.cx-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.cx-table th { text-align: left; font: 500 10.5px var(--cx-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--cx-ink-4); padding: 0 10px 8px; }
.cx-table td { border-top: 1px solid var(--cx-line); padding: 10px; vertical-align: top; }

/* templates gallery + pickers */
.cx-pick { display: grid; gap: 10px; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }
.cx-opt { text-align: left; border-radius: 14px; border: 1px solid var(--cx-line); background: var(--cx-glass); padding: 13px; display: grid; gap: 6px; cursor: pointer; color: inherit; transition: border-color .2s, transform .25s cubic-bezier(.2,.8,.2,1), background .2s; }
.cx-opt:hover { border-color: var(--cx-line-2); transform: translateY(-2px); }
.cx-opt[aria-pressed="true"], .cx-opt[aria-checked="true"] { border-color: transparent; box-shadow: 0 0 0 1.5px var(--cx-blue), 0 10px 30px -16px var(--cx-blue); background: color-mix(in srgb, var(--cx-blue) 8%, transparent); }
.cx-opt[disabled] { opacity: .45; cursor: not-allowed; transform: none; }
.cx-opt .cx-t { font-weight: 600; }
.cx-opt .cx-d { font-size: 12.5px; color: var(--cx-ink-3); }
.cx-steps { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 18px; }
.cx-step { display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 12px 0 6px; border-radius: 999px; border: 1px solid var(--cx-line); font-size: 12.5px; color: var(--cx-ink-3); }
.cx-step i { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font: 600 10.5px var(--cx-mono); font-style: normal; background: var(--cx-glass-2); }
.cx-step[data-on="1"] { color: var(--cx-ink); border-color: var(--cx-line-2); }
.cx-step[data-on="1"] i { background: var(--cx-energy); color: #fff; }
.cx-cost { position: sticky; top: 16px; display: grid; gap: 12px; }
.cx-big { font: 600 34px/1 var(--cx-display); letter-spacing: -.02em; }

/* tour */
.cx-tour { position: fixed; z-index: 80; max-width: 320px; border-radius: 16px; padding: 16px; background: color-mix(in srgb, var(--cx-bg) 88%, transparent); backdrop-filter: blur(20px) saturate(150%); -webkit-backdrop-filter: blur(20px) saturate(150%); border: 1px solid var(--cx-line-2); box-shadow: 0 20px 60px -20px rgba(0,0,0,.6), 0 0 0 1px rgba(121,166,255,.12); }
.cx-tour-ring { position: fixed; z-index: 79; pointer-events: none; border-radius: 14px; box-shadow: 0 0 0 2px var(--cx-blue), 0 0 0 9999px rgba(0,0,0,.45); transition: all .35s cubic-bezier(.2,.8,.2,1); }

/* phone: rail becomes a bottom tab bar; editing affordances are desktop-only, approvals stay */
@media (max-width: 860px) {
  .cx-shell { grid-template-columns: minmax(0, 1fr); }
  .cx-rail { position: fixed; inset: auto 0 0 0; top: auto; height: auto; z-index: 60; flex-direction: row; justify-content: space-around; padding: 6px 6px calc(6px + env(safe-area-inset-bottom)); border-right: 0; border-top: 1px solid var(--cx-line); }
  .cx-brand, .cx-nav-sep, .cx-rail-foot, .cx-nav-a.cx-desk { display: none; }
  .cx-nav-a { flex-direction: column; gap: 3px; font-size: 10.5px; padding: 6px 8px; }
  .cx-nav-a[aria-current="page"]::before { left: 30%; right: 30%; top: -7px; bottom: auto; width: auto; height: 2px; }
  .cx-main { padding: 20px 16px 96px; }
  .cx-s4, .cx-s5, .cx-s6, .cx-s7, .cx-s8 { grid-column: span 12; }
  .cx-desk-only { display: none !important; }
  .cx-cost { position: static; }
}
@media (min-width: 861px) { .cx-phone-only { display: none !important; } }
@media (prefers-reduced-motion: reduce) {
  .cx-aura::before, .cx-aura::after, .cx-reveal, .cx-pill.cx-wait::before { animation: none !important; }
  .cx-opt, .cx-btn, .cx-tour-ring { transition: none !important; }
}

toolu_013FjQT6BmRzpuE24YhMz1Qg.content:
/* Cyrus customer app (r39): the landing's language (black and white, crisp type, electric blue + violet energy,
   glass panels) for every customer page. Everything is scoped to .cx-app and prefixed cx- (no Tailwind collisions).
   Dark is the default; html[data-theme="light"] (the portal toggle) gets a real light theme. */
.cx-app {
  --cx-bg: #000; --cx-bg-2: #06070c; --cx-ink: #fff; --cx-ink-2: rgba(255,255,255,.74); --cx-ink-3: rgba(255,255,255,.56); --cx-ink-4: rgba(255,255,255,.36);
  --cx-line: rgba(255,255,255,.09); --cx-line-2: rgba(255,255,255,.16);
  --cx-blue: #3d7bff; --cx-blue-hi: #79a6ff; --cx-violet: #8b5cff; --cx-violet-hi: #b49bff;
  --cx-ok: #4ade9a; --cx-bad: #ff6b81; --cx-warn: #ffc56b;
  --cx-glass: linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.015)); --cx-glass-2: rgba(255,255,255,.06);
  --cx-energy: linear-gradient(100deg, var(--cx-blue), var(--cx-violet));
  --cx-display: var(--font-space), "Space Grotesk", var(--font-inter), system-ui, sans-serif;
  --cx-body: var(--font-inter), Inter, system-ui, sans-serif; --cx-mono: var(--font-jb), ui-monospace, monospace;
  --cx-r: 18px; --cx-r-sm: 12px;
  color-scheme: dark; background: var(--cx-bg); color: var(--cx-ink); font: 14.5px/1.55 var(--cx-body); -webkit-font-smoothing: antialiased;
  min-height: 100%; position: relative; isolation: isolate;
}
html[data-theme="light"] .cx-app {
  --cx-bg: #f6f7fb; --cx-bg-2: #ffffff; --cx-ink: #07080d; --cx-ink-2: rgba(7,8,13,.76); --cx-ink-3: rgba(7,8,13,.58); --cx-ink-4: rgba(7,8,13,.4);
  --cx-line: rgba(7,8,13,.09); --cx-line-2: rgba(7,8,13,.16); --cx-blue: #2459e0; --cx-blue-hi: #2459e0; --cx-violet: #6a3df0; --cx-violet-hi: #6a3df0;
  --cx-ok: #12865a; --cx-bad: #c8243f; --cx-warn: #9a5b00;
  --cx-glass: linear-gradient(180deg, #fff, #fbfbfe); --cx-glass-2: rgba(7,8,13,.04); color-scheme: light;
}
.cx-app *, .cx-app *::before, .cx-app *::after { box-sizing: border-box; }
.cx-app a { color: inherit; text-decoration: none; }
.cx-app :focus-visible { outline: 2px solid var(--cx-blue-hi); outline-offset: 3px; border-radius: 8px; }
.cx-app ::selection { background: var(--cx-violet); color: #fff; }

/* ambient energy behind the content (no motion when reduced) */
.cx-aura { position: absolute; inset: 0; z-index: -1; pointer-events: none; overflow: hidden; }
.cx-aura::before, .cx-aura::after { content: ""; position: absolute; width: 60vmax; height: 60vmax; border-radius: 50%; filter: blur(80px); opacity: .16; animation: cx-drift 26s ease-in-out infinite alternate; }
.cx-aura::before { background: radial-gradient(circle, var(--cx-blue), transparent 62%); top: -30vmax; right: -14vmax; }
.cx-aura::after { background: radial-gradient(circle, var(--cx-violet), transparent 62%); bottom: -36vmax; left: -18vmax; animation-delay: -9s; }
html[data-theme="light"] .cx-app .cx-aura::before, html[data-theme="light"] .cx-app .cx-aura::after { opacity: .07; }
@keyframes cx-drift { to { transform: translate3d(4vmax, 3vmax, 0) scale(1.08); } }

/* ---------- shell ---------- */
.cx-shell { display: grid; grid-template-columns: 232px minmax(0, 1fr); min-height: 100%; }
.cx-rail { position: sticky; top: 0; align-self: start; height: 100dvh; max-height: 100%; display: flex; flex-direction: column; gap: 4px; padding: 20px 14px; border-right: 1px solid var(--cx-line); background: color-mix(in srgb, var(--cx-bg) 70%, transparent); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); }
.cx-brand { display: flex; align-items: center; gap: 10px; padding: 4px 10px 18px; }
.cx-brand small { font: 500 10px var(--cx-mono); letter-spacing: .18em; text-transform: uppercase; color: var(--cx-ink-4); }
.cx-nav-a { display: flex; align-items: center; gap: 11px; padding: 9px 11px; border-radius: 11px; color: var(--cx-ink-3); font-weight: 500; transition: background .2s, color .2s; position: relative; }
.cx-nav-a svg { width: 17px; height: 17px; flex: none; }
.cx-nav-a:hover { color: var(--cx-ink); background: var(--cx-glass-2); }
.cx-nav-a[aria-current="page"] { color: var(--cx-ink); background: var(--cx-glass-2); box-shadow: inset 0 0 0 1px var(--cx-line-2); }
.cx-nav-a[aria-current="page"]::before { content: ""; position: absolute; left: -14px; top: 9px; bottom: 9px; width: 2px; border-radius: 2px; background: var(--cx-energy); }
.cx-nav-sep { height: 1px; background: var(--cx-line); margin: 10px 8px; }
.cx-rail-foot { margin-top: auto; display: grid; gap: 10px; padding: 10px; border-top: 1px solid var(--cx-line); }
.cx-rail-foot .cx-who { font-size: 12.5px; color: var(--cx-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cx-main { min-width: 0; padding: 28px clamp(16px, 3.4vw, 44px) 64px; }
.cx-page { max-width: 1180px; margin: 0 auto; }

/* ---------- type ---------- */
.cx-eyebrow { font: 500 10.5px var(--cx-mono); letter-spacing: .2em; text-transform: uppercase; color: var(--cx-ink-4); }
.cx-h1 { font: 600 clamp(26px, 3.2vw, 36px)/1.08 var(--cx-display); letter-spacing: -.02em; margin: 6px 0 0; }
.cx-h2 { font: 600 17px/1.2 var(--cx-display); letter-spacing: -.01em; margin: 0; }
.cx-sub { color: var(--cx-ink-3); margin: 8px 0 0; max-width: 64ch; }
.cx-mono { font-family: var(--cx-mono); font-size: 12px; letter-spacing: .02em; }
.cx-muted { color: var(--cx-ink-3); }
.cx-faint { color: var(--cx-ink-4); }
.cx-grad { background: var(--cx-energy); -webkit-background-clip: text; background-clip: text; color: transparent; }
.cx-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }

/* ---------- glass cards ---------- */
.cx-card { position: relative; border-radius: var(--cx-r); background: var(--cx-glass); border: 1px solid var(--cx-line); padding: 18px; overflow: hidden; }
html[data-theme="light"] .cx-app .cx-card { box-shadow: 0 1px 0 rgba(7,8,13,.03), 0 8px 24px -16px rgba(7,8,13,.18); }
.cx-card-h { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
.cx-card-h .cx-aside { margin-left: auto; font: 500 11px var(--cx-mono); color: var(--cx-ink-4); }
.cx-glyph { width: 32px; height: 32px; border-radius: 10px; display: grid; place-items: center; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); flex: none; }
.cx-glyph svg { width: 16px; height: 16px; }
.cx-grid { display: grid; gap: 14px; grid-template-columns: repeat(12, minmax(0, 1fr)); }
.cx-s4 { grid-column: span 4; } .cx-s5 { grid-column: span 5; } .cx-s6 { grid-column: span 6; } .cx-s7 { grid-column: span 7; } .cx-s8 { grid-column: span 8; } .cx-s12 { grid-column: span 12; }
.cx-reveal { animation: cx-in .5s cubic-bezier(.2,.8,.2,1) both; animation-delay: var(--d, 0s); }
@keyframes cx-in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- controls ---------- */
.cx-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 38px; padding: 0 16px; border-radius: 999px; border: 1px solid var(--cx-line-2); background: transparent; color: var(--cx-ink); font: 600 13.5px var(--cx-body); cursor: pointer; transition: background .2s, border-color .2s, transform .2s, opacity .2s; white-space: nowrap; }
.cx-btn:hover { background: var(--cx-glass-2); border-color: var(--cx-ink-4); }
.cx-btn:active { transform: translateY(1px); }
.cx-btn[disabled], .cx-btn[aria-disabled="true"] { opacity: .45; cursor: not-allowed; }
.cx-btn-pri { background: var(--cx-ink); color: var(--cx-bg); border-color: transparent; }
.cx-btn-pri:hover { background: var(--cx-ink); opacity: .9; }
.cx-btn-energy { background: var(--cx-energy); color: #fff; border-color: transparent; box-shadow: 0 8px 28px -10px rgba(110,100,255,.7); }
.cx-btn-energy:hover { opacity: .92; background: var(--cx-energy); }
.cx-btn-danger { color: var(--cx-bad); border-color: color-mix(in srgb, var(--cx-bad) 40%, transparent); }
.cx-btn-sm { height: 30px; padding: 0 12px; font-size: 12.5px; }
.cx-input, .cx-select, .cx-textarea { width: 100%; height: 40px; border-radius: 12px; border: 1px solid var(--cx-line-2); background: var(--cx-bg-2); color: var(--cx-ink); padding: 0 12px; font: 14px var(--cx-body); transition: border-color .2s, box-shadow .2s; }
.cx-textarea { height: auto; min-height: 120px; padding: 12px; line-height: 1.55; resize: vertical; }
.cx-input:focus, .cx-select:focus, .cx-textarea:focus { outline: none; border-color: var(--cx-blue); box-shadow: 0 0 0 3px color-mix(in srgb, var(--cx-blue) 25%, transparent); }
.cx-label { display: grid; gap: 6px; font-size: 12.5px; color: var(--cx-ink-3); font-weight: 500; }
.cx-check { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; font-size: 13.5px; color: var(--cx-ink-2); }
.cx-check input { width: 16px; height: 16px; accent-color: var(--cx-blue); }
.cx-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 999px; border: 1px solid var(--cx-line-2); background: var(--cx-glass-2); flex-wrap: wrap; }
.cx-seg a, .cx-seg button { height: 30px; padding: 0 13px; border-radius: 999px; display: inline-flex; align-items: center; font-size: 13px; color: var(--cx-ink-3); background: none; border: 0; cursor: pointer; }
.cx-seg [aria-current="page"], .cx-seg [aria-pressed="true"] { background: var(--cx-ink); color: var(--cx-bg); font-weight: 600; }

/* ---------- data bits ---------- */
.cx-pill { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 9px; border-radius: 999px; font: 500 11px var(--cx-mono); letter-spacing: .02em; border: 1px solid var(--cx-line-2); color: var(--cx-ink-3); white-space: nowrap; }
.cx-pill::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .9; }
.cx-pill.cx-ok { color: var(--cx-ok); border-color: color-mix(in srgb, var(--cx-ok) 35%, transparent); }
.cx-pill.cx-bad { color: var(--cx-bad); border-color: color-mix(in srgb, var(--cx-bad) 35%, transparent); }
.cx-pill.cx-warn { color: var(--cx-warn); border-color: color-mix(in srgb, var(--cx-warn) 35%, transparent); }
.cx-pill.cx-wait { color: var(--cx-blue-hi); border-color: color-mix(in srgb, var(--cx-blue) 40%, transparent); }
.cx-pill.cx-wait::before { animation: cx-pulse 1.4s ease-in-out infinite; }
.cx-pill.cx-none::before { display: none; }
@keyframes cx-pulse { 50% { opacity: .25; } }
.cx-stat { display: grid; gap: 2px; }
.cx-stat b { font: 600 28px/1.05 var(--cx-display); letter-spacing: -.02em; }
.cx-stat span { font-size: 12px; color: var(--cx-ink-3); }
.cx-meter { height: 6px; border-radius: 999px; background: var(--cx-glass-2); overflow: hidden; }
.cx-meter > i { display: block; height: 100%; border-radius: inherit; background: var(--cx-energy); }
.cx-list { display: grid; }
.cx-row { display: flex; align-items: center; gap: 12px; padding: 11px 2px; border-top: 1px solid var(--cx-line); min-width: 0; }
.cx-row:first-child { border-top: 0; }
.cx-row .cx-grow { flex: 1; min-width: 0; }
.cx-row .cx-t { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cx-row .cx-d { font-size: 12.5px; color: var(--cx-ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
a.cx-row { border-radius: 10px; transition: background .2s; padding-left: 8px; padding-right: 8px; margin: 0 -8px; }
a.cx-row:hover { background: var(--cx-glass-2); }
.cx-empty { display: grid; place-items: center; text-align: center; gap: 10px; padding: 26px 12px; color: var(--cx-ink-3); }
.cx-tile { width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center; font: 600 12px var(--cx-mono); background: var(--cx-glass-2); border: 1px solid var(--cx-line-2); flex: none; }
.cx-tile.cx-energy { background: var(--cx-energy); color: #fff; border: 0; }
.cx-note { border-radius: 12px; border: 1px dashed var(--cx-line-2); padding: 11px 13px; font-size: 13px; color: var(--cx-ink-3); }
.cx-note b { color: var(--cx-ink-2); }
.cx-error { color: var(--cx-bad); font-size: 13px; }
.cx-okmsg { color: var(--cx-ok); font-size: 13px; }
.cx-code { font: 12.5px var(--cx-mono); background: var(--cx-bg-2); border: 1px solid var(--cx-line-2); border-radius: 10px; padding: 10px 12px; word-break: break-all; user-select: all; }
.cx-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.cx-table th { text-align: left; font: 500 10.5px var(--cx-mono); letter-spacing: .14em; text-transform: uppercase; color: var(--cx-ink-4); padding: 0 10px 8px; }
.cx-table td { border-top: 1px solid var(--cx-line); padding: 10px; vertical-align: top; }

/* templates gallery + pickers */
.cx-pick { display: grid; gap: 10px; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }
.cx-opt { text-align: left; border-radius: 14px; border: 1px solid var(--cx-line); background: var(--cx-glass); padding: 13px; display: grid; gap: 6px; cursor: pointer; color: inherit; transition: border-color .2s, transform .25s cubic-bezier(.2,.8,.2,1), background .2s; }
.cx-opt:hover { border-color: var(--cx-line-2); transform: translateY(-2px); }
.cx-opt[aria-pressed="true"], .cx-opt[aria-checked="true"] { border-color: transparent; box-shadow: 0 0 0 1.5px var(--cx-blue), 0 10px 30px -16px var(--cx-blue); background: color-mix(in srgb, var(--cx-blue) 8%, transparent); }
.cx-opt[disabled] { opacity: .45; cursor: not-allowed; transform: none; }
.cx-opt .cx-t { font-weight: 600; }
.cx-opt .cx-d { font-size: 12.5px; color: var(--cx-ink-3); }
.cx-steps { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 18px; }
.cx-step { display: inline-flex; align-items: center; gap: 8px; height: 30px; padding: 0 12px 0 6px; border-radius: 999px; border: 1px solid var(--cx-line); font-size: 12.5px; color: var(--cx-ink-3); }
.cx-step i { width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font: 600 10.5px var(--cx-mono); font-style: normal; background: var(--cx-glass-2); }
.cx-step[data-on="1"] { color: var(--cx-ink); border-color: var(--cx-line-2); }
.cx-step[data-on="1"] i { background: var(--cx-energy); color: #fff; }
.cx-cost { position: sticky; top: 16px; display: grid; gap: 12px; }
.cx-big { font: 600 34px/1 var(--cx-display); letter-spacing: -.02em; }

/* tour */
.cx-tour { position: fixed; z-index: 80; max-width: 320px; border-radius: 16px; padding: 16px; background: color-mix(in srgb, var(--cx-bg) 88%, transparent); backdrop-filter: blur(20px) saturate(150%); -webkit-backdrop-filter: blur(20px) saturate(150%); border: 1px solid var(--cx-line-2); box-shadow: 0 20px 60px -20px rgba(0,0,0,.6), 0 0 0 1px rgba(121,166,255,.12); }
.cx-tour-ring { position: fixed; z-index: 79; pointer-events: none; border-radius: 14px; box-shadow: 0 0 0 2px var(--cx-blue), 0 0 0 9999px rgba(0,0,0,.45); transition: all .35s cubic-bezier(.2,.8,.2,1); }

/* phone: rail becomes a bottom tab bar; editing affordances are desktop-only, approvals stay */
@media (max-width: 860px) {
  .cx-shell { grid-template-columns: minmax(0, 1fr); }
  .cx-rail { position: fixed; inset: auto 0 0 0; top: auto; height: auto; z-index: 60; flex-direction: row; justify-content: space-around; padding: 6px 6px calc(6px + env(safe-area-inset-bottom)); border-right: 0; border-top: 1px solid var(--cx-line); }
  .cx-brand, .cx-nav-sep, .cx-rail-foot, .cx-nav-a.cx-desk { display: none; }
  .cx-nav-a { flex-direction: column; gap: 3px; font-size: 10.5px; padding: 6px 8px; }
  .cx-nav-a[aria-current="page"]::before { left: 30%; right: 30%; top: -7px; bottom: auto; width: auto; height: 2px; }
  .cx-main { padding: 20px 16px 96px; }
  .cx-s4, .cx-s5, .cx-s6, .cx-s7, .cx-s8 { grid-column: span 12; }
  .cx-desk-only { display: none !important; }
  .cx-cost { position: static; }
}
@media (min-width: 861px) { .cx-phone-only { display: none !important; } }
@media (prefers-reduced-motion: reduce) {
  .cx-aura::before, .cx-aura::after, .cx-reveal, .cx-pill.cx-wait::before { animation: none !important; }
  .cx-opt, .cx-btn, .cx-tour-ring { transition: none !important; }
}

