// Line icons for the Cyrus customer app (r39), drawn in the landing's 1.5 px stroke style.
import type { SVGProps } from "react";

const P = { viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.5, strokeLinecap: "round", strokeLinejoin: "round" } as const;
type I = SVGProps<SVGSVGElement>;
