export const IconPlus = (p: I) => <svg {...P} {...p} aria-hidden="true"><path d="M12 5v14M5 12h14" /></svg>;
export const IconStack = (p: I) => <svg {...P} {...p} aria-hidden="true"><path d="m12 3 9 5-9 5-9-5z" /><path d="m3 13 9 5 9-5" /></svg>;
export const IconStudio = (p: I) => <svg {...P} {...p} aria-hidden="true"><rect x="3" y="4" width="18" height="14" rx="2" /><path d="M8 21h8M12 18v3M7 9l3 3-3 3M12 15h5" /></svg>;
export const IconUser = (p: I) => <svg {...P} {...p} aria-hidden="true"><circle cx="12" cy="8" r="4" /><path d="M4 21a8 8 0 0 1 16 0" /></svg>;
export const IconServer = (p: I) => <svg {...P} {...p} aria-hidden="true"><rect x="3" y="4" width="18" height="7" rx="2" /><rect x="3" y="13" width="18" height="7" rx="2" /><path d="M7 7.5h.01M7 16.5h.01" /></svg>;
export const IconBolt = (p: I) => <svg {...P} {...p} aria-hidden="true"><path d="M13 2 4 14h7l-1 8 9-12h-7z" /></svg>;
export const IconBox = (p: I) => <svg {...P} {...p} aria-hidden="true"><path d="m12 2 9 5v10l-9 5-9-5V7z" /><path d="m3 7 9 5 9-5M12 12v10" /></svg>;
export const IconKey = (p: I) => <svg {...P} {...p} aria-hidden="true"><circle cx="8" cy="15" r="4" /><path d="m11 12 9-9M17 6l3 3M15 8l2 2" /></svg>;
