              {([["Published", counts.published], ["In review", counts.pending], ["Held", counts.held], ["Removed", counts.removed]] as const).map(([k, x]) => <div key={k} className="cx-stat"><b style={{ fontSize: 22 }}>{n(x)}</b><span>{k}</span></div>)}
            </div>
          ) : <Empty>Nothing contributed yet. Assets you make in the studios can be shared with the library.</Empty>}
        </Card>

        <Card title="Activity" icon={<IconPulse />} className="cx-s12" d={0.16}>
          {feed.length ? (
            <div className="cx-list">
              {feed.map((a, i) => {
                const body = (<><span className={`cx-pill cx-${a.tone === "neutral" ? "none" : a.tone}`}>{a.kind}</span><span className="cx-grow cx-t" style={{ fontWeight: 500 }}>{a.text}</span><span className="cx-mono cx-faint">{ago(a.at, now)}</span></>);
                return a.href ? <a key={i} className="cx-row" href={a.href}>{body}</a> : <div key={i} className="cx-row">{body}</div>;
              })}
            </div>
          ) : <Empty>Nothing yet.</Empty>}
        </Card>
      </div>
      <Tour />
    </>
  );
}

