"use client";
// Project page actions (r39): install the current version on a server (the same install plan + acknowledgements
// the studio's dialog uses, enforced again by the API), and roll back by making an earlier build current.
// Both are approvals, so they stay on the phone; editing lives in the studios (desktop).
import { useState } from "react";
import { useRouter } from "next/navigation";

export type PlanView = { serverId: string; serverName: string; ready: boolean; why: string | null; op: string; blockers: string[]; warnings: { id: string; text: string }[]; restart: string; players: string | null; backupNote: string };

export function InstallPanel({ buildId, plans }: { buildId: string; plans: PlanView[] }) {
  const ready = plans.filter((p) => p.ready);
  const [sid, setSid] = useState(ready[0]?.serverId ?? "");
  const [acked, setAcked] = useState<string[]>([]);
  const [restart, setRestart] = useState(false);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const plan = plans.find((p) => p.serverId === sid) ?? null;
  if (!plans.length) return <p className="cx-note">No Minecraft server on your Nxeon account. Download the jar instead, or rent a server at Nxeon.</p>;
  const allAcked = !!plan && plan.warnings.every((w) => acked.includes(w.id));
  const go = async () => {
    if (!plan) return; setBusy(true); setMsg(null);
    try {
      const r = await fetch(`/api/mod-builder/builds/${encodeURIComponent(buildId)}/install`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ serverId: plan.serverId, acked, restart: restart && plan.restart === "required" }) });
      const j = (await r.json().catch(() => ({}))) as { ok?: boolean; error?: string; queued?: boolean; restartNote?: string | null; restarted?: boolean };
      if (!r.ok || !j.ok) setMsg({ ok: false, text: j.error || `Install failed (${r.status}).` });
      else setMsg({ ok: true, text: j.queued ? "Queued: it installs as soon as the server is ready." : `Installed on ${plan.serverName}.${j.restarted ? " The server restarted." : ""}${j.restartNote ? ` ${j.restartNote}` : ""}` });
    } catch { setMsg({ ok: false, text: "Network error. Nothing was changed." }); }
    setBusy(false);
  };
  return (
    <div style={{ display: "grid", gap: 12 }}>
      <label className="cx-label">Server
        <select className="cx-select" value={sid} onChange={(e) => { setSid(e.target.value); setAcked([]); setMsg(null); }}>
          {plans.map((p) => <option key={p.serverId} value={p.serverId} disabled={!p.ready}>{p.serverName}{p.ready ? "" : ` (${p.why ?? "not ready"})`}</option>)}
        </select>
      </label>
      {plan ? (
        <>
          {plan.blockers.map((b) => <p key={b} className="cx-error" style={{ margin: 0 }}>{b}</p>)}
          {plan.warnings.length ? (
            <fieldset style={{ border: 0, padding: 0, margin: 0, display: "grid", gap: 8 }}>
              <legend className="cx-eyebrow" style={{ marginBottom: 6 }}>Please confirm</legend>
              {plan.warnings.map((w) => (
                <label key={w.id} className="cx-check"><input type="checkbox" checked={acked.includes(w.id)} onChange={(e) => setAcked(e.target.checked ? [...acked, w.id] : acked.filter((x) => x !== w.id))} />{w.text}</label>
              ))}
            </fieldset>
          ) : null}
          <div className="cx-mono cx-faint">{plan.op === "update" ? "Updates the installed version" : plan.op === "none" ? "This version is already installed" : "New install"} · {plan.restart === "required" ? "needs a restart" : plan.restart === "hot" ? "loads without a restart" : "no restart"} · {plan.backupNote}</div>
          {plan.players ? <p className="cx-note" style={{ margin: 0 }}>{plan.players}</p> : null}
          {plan.restart === "required" ? <label className="cx-check"><input type="checkbox" checked={restart} onChange={(e) => setRestart(e.target.checked)} />Restart the server after installing</label> : null}
          <div><button type="button" className="cx-btn cx-btn-pri" disabled={busy || !plan.ready || plan.blockers.length > 0 || !allAcked || plan.op === "none"} onClick={go}>{busy ? "Installing…" : `Install on ${plan.serverName}`}</button></div>
        </>
      ) : null}
      {msg ? <p className={msg.ok ? "cx-okmsg" : "cx-error"} role="status" style={{ margin: 0 }}>{msg.text}</p> : null}
    </div>
  );
}

export function MakeCurrent({ projectId, buildId, label = "Make current" }: { projectId: string; buildId: string; label?: string }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const go = async () => {
    if (!confirm("Make this version the current one? Installs keep running what they have until you install again.")) return;
    setBusy(true); setErr(null);
    const r = await fetch(`/api/mod-builder/projects/${encodeURIComponent(projectId)}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ headBuildId: buildId }) }).catch(() => null);
    const j = (await r?.json().catch(() => ({}))) as { ok?: boolean; error?: string } | undefined;
    setBusy(false);
    if (!r || !r.ok || !j?.ok) { setErr(j?.error || "Could not roll back."); return; }
    router.refresh();
  };
  return <>{err ? <span className="cx-error">{err}</span> : null}<button type="button" className="cx-btn cx-btn-sm" onClick={go} disabled={busy}>{busy ? "…" : label}</button></>;
}

