import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { toView } from "@/lib/cyrus/builder/view";
import { groupProjects } from "@/lib/cyrus/projects";
import { buildRows, ago, flightBadge } from "@/lib/cyrus/app/view";
import { modBuilderServers } from "@/lib/modbuilder/install";
import { installPlansFor } from "@/lib/cyrus/lifecycle/server";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { configStudioViewer } from "@/lib/cyrus/config/deps";
import { designerStudioOn } from "@/lib/cyrus/designer/studio/deps";
import { DATAPACK_STUDIO_FLAG } from "@/lib/cyrus/datapack/studio-view";
import { LIBRARY_BROWSE_FLAG } from "@/lib/cyrus/library/v2/browse";
import { Card, Empty, Flight, BuildStatus } from "@/components/cyrus/app/ui";
import { InstallPanel, MakeCurrent, type PlanView } from "@/components/cyrus/app/ProjectActions";
import { IconBox, IconDownload, IconFlight, IconRewind, IconServer, IconStack, IconStudio } from "@/components/cyrus/app/icons";
import { appViewer, P, studioHref } from "../../_gate";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Cyrus · Project", robots: { index: false } };

/** One project (r39): its builds with Test Flight, engine revisions, install + rollback, and links into the studios. */
export default async function CyrusProjectPage({ params }: { params: Promise<{ rootId: string }> }) {
  const v = await appViewer();
  const { rootId } = await params;
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(rootId)) notFound();
  // ownership: only this user's builds of this chain; a stranger's id is the same 404 as a missing one
  const rows = await db.modBuild.findMany({ where: { userId: v.user.id, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" }, take: 200 });
  if (!rows.some((r) => r.id === rootId)) notFound();
  const project = groupProjects(rows.map(toView)).find((p) => p.rootId === rootId);
  if (!project) notFound();
  const now = new Date();
  const head = project.head, headRow = head ? rows.find((r) => r.id === head.id)! : null;
  const latest = project.latest;

  const engine = await db.cyrusProject.findFirst({ where: { rootBuildId: rootId, userId: v.user.id }, select: { id: true, headRevisionId: true, lastPassingRevisionId: true, revisionCount: true } }).catch(() => null);
  const [revisions, servers, plans, studios] = await Promise.all([
    engine ? db.cyrusRevision.findMany({ where: { projectId: engine.id }, orderBy: { seq: "desc" }, take: 20, select: { id: true, seq: true, kind: true, status: true, message: true, createdAt: true, modBuildId: true } }) : Promise.resolve([]),
    modBuilderServers(v.user.id).catch(() => []),
    headRow ? installPlansFor(headRow, v.user.id).then((r) => r.plans).catch(() => []) : Promise.resolve([]),
    (async () => {
      const [model, config] = await Promise.all([modelStudioViewer().catch(() => null), configStudioViewer().catch(() => null)]);
      const designer = designerStudioOn();
      return [
        { id: "texture", label: "Texture", on: !!model }, { id: "sound", label: "Sound", on: !!model }, { id: "model", label: "3D model", on: !!model },
        { id: "motion", label: "Motion", on: !!model && designer }, { id: "items", label: "Items", on: designer }, { id: "menus", label: "Menus and quests", on: designer },
        { id: "bosses", label: "Bosses", on: designer }, { id: "config", label: "Config", on: !!config },
        { id: "datapacks", label: "Data packs", on: process.env[DATAPACK_STUDIO_FLAG] === "1" }, { id: "library", label: "Library", on: process.env[LIBRARY_BROWSE_FLAG] === "1" },
      ].filter((s) => s.on);
    })(),
  ]);
  const byId = new Map(servers.map((s) => [s.id, s]));
  const planViews: PlanView[] = plans.map((p) => {
    const s = byId.get(p.server.id);
    return { serverId: p.server.id, serverName: p.server.name, ready: !!s?.compatible, why: s?.reason ?? (s ? null : "not a plugin server"), op: p.plan.op, blockers: p.plan.blockers, warnings: p.plan.warnings, restart: p.plan.restart, players: p.plan.players.needed ? p.plan.players.text : null, backupNote: p.plan.backupNote };
  });
  const list = buildRows(project);
  const target = head?.id ?? latest.id;
  const studioBase = v.onCyrus ? "/studio" : "/dashboard/cyrus";

  return (
    <>
      <nav className="cx-mono cx-faint" aria-label="Breadcrumb" style={{ marginBottom: 10 }}><a href={v.href(P.home)}>Home</a> / <a href={v.href(P.projects)}>Projects</a></nav>
      <header className="cx-head">
        <div>
          <div className="cx-eyebrow">Project</div>
          <h1 className="cx-h1">{project.title}</h1>
          <p className="cx-sub">{head ? <>Current version {head.version ? <b>v{head.version}</b> : "built"} for Minecraft {head.mcVersion}, {ago(head.finishedAt || head.createdAt, now)}.</> : "No finished build yet."} {project.builds.length} build{project.builds.length === 1 ? "" : "s"}{engine ? `, ${engine.revisionCount} revision${engine.revisionCount === 1 ? "" : "s"}` : ""}.</p>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          {head ? <Flight f={flightBadge(head)} /> : null}
          {head?.jarName ? <a className="cx-btn" href={`/api/mod-builder/builds/${encodeURIComponent(head.id)}/jar`}><IconDownload width={16} height={16} />Download jar</a> : null}
          <a className="cx-btn cx-btn-pri" href={`${studioBase}/${encodeURIComponent(target)}`}>Open in studio</a>
        </div>
      </header>

      <div className="cx-grid">
        <Card title="Builds" icon={<IconFlight />} className="cx-s8" aside="newest first">
          <div className="cx-list">
            {list.map((b) => (
              <div key={b.id} className="cx-row" style={{ flexWrap: "wrap" }}>
                <span className="cx-grow" style={{ minWidth: 200 }}>
                  <span className="cx-t" style={{ display: "block" }}>{b.version ? `v${b.version} · ` : ""}{b.label}</span>
                  <span className="cx-d" style={{ display: "block" }}>Minecraft {b.mcVersion} · {ago(b.finishedAt || b.createdAt, now)}{b.installedOn ? ` · installed on ${b.installedOn}` : ""}{b.error ? ` · ${b.error}` : ""}</span>
                </span>
                <BuildStatus status={b.status} />
                {b.status === "succeeded" ? <Flight f={b.flight} /> : null}
                {b.head ? <span className="cx-pill cx-ok">Current</span> : b.status === "succeeded" ? <MakeCurrent projectId={rootId} buildId={b.id} label="Roll back to this" /> : null}
              </div>
            ))}
          </div>
        </Card>

        <Card title="Install" icon={<IconServer />} className="cx-s4" d={0.05}>
          {head ? <InstallPanel buildId={head.id} plans={planViews} /> : <Empty>Install becomes available once a build finishes.</Empty>}
        </Card>

        <Card title="Studios" icon={<IconStudio />} className="cx-s7" d={0.08} aside={<span className="cx-phone-only">editing is on desktop</span>}>
          {studios.length ? (
            <div className="cx-pick" style={{ gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))" }}>
              {studios.map((s) => <a key={s.id} className="cx-opt cx-desk-only" href={studioHref(target, s.id).replace("/dashboard/cyrus", studioBase)}><span className="cx-t">{s.label}</span><span className="cx-d">Open the {s.label.toLowerCase()} studio</span></a>)}
              <span className="cx-phone-only cx-muted">Open this project on a computer to edit textures, sounds, models and designs.</span>
            </div>
          ) : <Empty>The studios are not switched on for this account yet. Changes are made by describing them in the studio chat.</Empty>}
        </Card>

        <Card title="Revisions" icon={<IconRewind />} className="cx-s5" d={0.1} aside={engine?.lastPassingRevisionId ? "last passing kept" : undefined}>
          {revisions.length ? (
            <div className="cx-list">
              {revisions.map((r) => (
                <div key={r.id} className="cx-row">
                  <span className="cx-tile">{r.seq}</span>
                  <span className="cx-grow"><span className="cx-t" style={{ display: "block", fontWeight: 500 }}>{r.message || { generated: "Generated", edited: "Edited in a studio", imported: "Imported", asset: "Asset change", revert: "Reverted" }[r.kind] || r.kind}</span><span className="cx-d" style={{ display: "block" }}>{r.kind} · {ago(r.createdAt.toISOString(), now)}{r.id === engine?.headRevisionId ? " · head" : ""}</span></span>
                  <span className={`cx-pill ${r.status === "passed" ? "cx-ok" : r.status === "failed" ? "cx-bad" : "cx-wait"}`}>{r.status}</span>
                </div>
              ))}
            </div>
          ) : <Empty>No engine revisions recorded for this project (builds made before revisions existed have none).</Empty>}
        </Card>

        <Card title="About" icon={<IconBox />} className="cx-s12" d={0.12}>
          <div className="cx-list">
            <div className="cx-row"><span className="cx-grow cx-muted">First prompt</span><span style={{ maxWidth: "70%", textAlign: "right" }}>{project.builds[0].prompt.slice(0, 300)}{project.builds[0].prompt.length > 300 ? "…" : ""}</span></div>
            {project.meta.notes ? <div className="cx-row"><span className="cx-grow cx-muted">Notes</span><span style={{ maxWidth: "70%", textAlign: "right", whiteSpace: "pre-wrap" }}>{project.meta.notes.slice(0, 600)}</span></div> : null}
            <div className="cx-row"><span className="cx-grow cx-muted">Change it</span><a className="cx-btn cx-btn-sm" href={`${studioBase}/${encodeURIComponent(target)}`}><IconStack width={14} height={14} />Describe a change in the studio</a></div>
          </div>
        </Card>
      </div>
    </>
  );
}

