"use client";
// Account panels (r39): API keys (create / revoke, the key shown once), notification preferences, data requests,
// grant revoke. All writes are server actions that re-check the viewer.
import { useState } from "react";
import { useRouter } from "next/navigation";
import type { ApiKeyView, PersonalScope } from "@/lib/cyrus/app/apikeys";
import { createApiKeyAction, revokeApiKeyAction, savePrefsAction, requestDataAction, cancelDataRequestAction, revokeGrantAction } from "@/app/dashboard/cyrus/app/account/actions";

const date = (iso: string | null) => (iso ? new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }) : "never");

export function ApiKeysPanel({ initial, scopes }: { initial: ApiKeyView[]; scopes: { id: PersonalScope; label: string }[] }) {
  const [keys, setKeys] = useState(initial);
  const [name, setName] = useState("");
  const [picked, setPicked] = useState<string[]>(["projects:read", "builds:read"]);
  const [expiry, setExpiry] = useState(90);
  const [fresh, setFresh] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [copied, setCopied] = useState(false);
  const create = async (e: React.FormEvent) => {
    e.preventDefault(); setBusy(true); setErr(null); setFresh(null);
    const r = await createApiKeyAction({ name, scopes: picked, expiryDays: expiry }).catch(() => ({ ok: false as const, error: "Could not create the key." }));
    setBusy(false);
    if (!r.ok) { setErr(r.error); return; }
    setFresh(r.key); setKeys([r.view, ...keys]); setName("");
  };
  const revoke = async (id: string) => {
    if (!confirm("Revoke this key? Anything using it stops working immediately.")) return;
    const r = await revokeApiKeyAction(id).catch(() => ({ ok: false as const, error: "Could not revoke." }));
    if (!r.ok) { setErr(r.error); return; }
    setKeys(r.keys);
  };
  return (
    <div style={{ display: "grid", gap: 18 }}>
      {fresh ? (
        <div className="cx-card" style={{ borderColor: "var(--cx-blue)" }} role="status">
          <div className="cx-eyebrow">New key: copy it now</div>
          <p className="cx-muted" style={{ margin: "6px 0 10px", fontSize: 13 }}>This is the only time it is shown. Cyrus keeps a hash, not the key.</p>
          <div className="cx-code" data-testid="new-key">{fresh}</div>
          <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
            <button type="button" className="cx-btn cx-btn-sm" onClick={() => navigator.clipboard?.writeText(fresh).then(() => setCopied(true)).catch(() => {})}>{copied ? "Copied" : "Copy"}</button>
            <button type="button" className="cx-btn cx-btn-sm" onClick={() => { setFresh(null); setCopied(false); }}>Done</button>
          </div>
        </div>
      ) : null}
      <form onSubmit={create} className="cx-desk-only" style={{ display: "grid", gap: 12 }}>
        <div className="cx-grid">
          <label className="cx-label cx-s8">Name<input className="cx-input" value={name} onChange={(e) => setName(e.target.value)} maxLength={48} placeholder="CI pipeline" required /></label>
          <label className="cx-label cx-s4">Expires
            <select className="cx-select" value={expiry} onChange={(e) => setExpiry(Number(e.target.value))}>
              <option value={30}>in 30 days</option><option value={90}>in 90 days</option><option value={365}>in a year</option><option value={0}>never</option>
            </select>
          </label>
        </div>
        <fieldset style={{ border: 0, padding: 0, margin: 0 }}>
          <legend className="cx-eyebrow" style={{ marginBottom: 8 }}>Permissions</legend>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 8 }}>
            {scopes.map((s) => (
              <label key={s.id} className="cx-check"><input type="checkbox" checked={picked.includes(s.id)} onChange={(e) => setPicked(e.target.checked ? [...picked, s.id] : picked.filter((x) => x !== s.id))} /><span>{s.label} <span className="cx-mono cx-faint">{s.id}</span></span></label>
            ))}
          </div>
        </fieldset>
        <div><button className="cx-btn cx-btn-pri" disabled={busy || !name.trim() || !picked.length}>{busy ? "Creating…" : "Create key"}</button></div>
      </form>
      <p className="cx-phone-only cx-note" style={{ margin: 0 }}>Create keys on a computer. You can revoke them here.</p>
      {err ? <p className="cx-error" role="alert" style={{ margin: 0 }}>{err}</p> : null}
      {keys.length ? (
        <div className="cx-list">
          {keys.map((k) => (
            <div key={k.id} className="cx-row" style={{ flexWrap: "wrap" }}>
              <span className="cx-grow" style={{ minWidth: 200 }}>
                <span className="cx-t" style={{ display: "block" }}>{k.name} <span className="cx-mono cx-faint">cyk_{k.prefix}_…</span></span>
                <span className="cx-d" style={{ display: "block" }}>{k.scopes.join(", ")} · created {date(k.createdAt)} · used {date(k.lastUsedAt)}{k.expiresAt ? ` · expires ${date(k.expiresAt)}` : ""}</span>
              </span>
              {k.active ? <><span className="cx-pill cx-ok">Active</span><button type="button" className="cx-btn cx-btn-sm cx-btn-danger" onClick={() => revoke(k.id)}>Revoke</button></> : <span className="cx-pill cx-none">{k.revokedAt ? "Revoked" : "Expired"}</span>}
            </div>
          ))}
        </div>
      ) : <p className="cx-muted" style={{ margin: 0 }}>No keys yet.</p>}
    </div>
  );
}

export function PrefsForm({ events, prefs }: { events: { id: string; label: string; hint: string; locked: boolean }[]; prefs: Record<string, { email: boolean; inApp: boolean }> }) {
  const [msg, setMsg] = useState<{ ok: boolean; t: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const submit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault(); setBusy(true); setMsg(null);
    const fd = new FormData(e.currentTarget);
    const r = await savePrefsAction([...fd.entries()].map(([k, v]) => [k, String(v)] as [string, string])).catch(() => ({ ok: false as const, error: "Could not save." }));
    setBusy(false); setMsg(r.ok ? { ok: true, t: "Saved." } : { ok: false, t: r.error });
  };
  return (
    <form onSubmit={submit} style={{ display: "grid", gap: 14 }}>
      <table className="cx-table">
        <thead><tr><th>Event</th><th style={{ width: 80 }}>Email</th><th style={{ width: 80 }}>In app</th></tr></thead>
        <tbody>
          {events.map((ev) => (
            <tr key={ev.id}>
              <td><b style={{ fontWeight: 600 }}>{ev.label}</b><div className="cx-faint" style={{ fontSize: 12.5 }}>{ev.hint}</div></td>
              {(["email", "inApp"] as const).map((ch) => (
                <td key={ch}><label className="cx-check"><input type="checkbox" name={`${ev.id}.${ch}`} defaultChecked={prefs[ev.id]?.[ch]} disabled={ev.locked} aria-label={`${ev.label}: ${ch === "email" ? "email" : "in app"}`} /></label></td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      <div style={{ display: "flex", gap: 12, alignItems: "center" }}><button className="cx-btn cx-btn-pri" disabled={busy}>{busy ? "Saving…" : "Save preferences"}</button>{msg ? <span className={msg.ok ? "cx-okmsg" : "cx-error"} role="status">{msg.t}</span> : null}</div>
    </form>
  );
}

export function DataPanel({ requests, confirmPhrase }: { requests: { id: string; kind: string; status: string; createdAt: string }[]; confirmPhrase: string }) {
  const router = useRouter();
  const [confirm, setConfirm] = useState("");
  const [msg, setMsg] = useState<{ ok: boolean; t: string } | null>(null);
  const run = async (kind: "export" | "delete") => {
    setMsg(null);
    const r = await requestDataAction({ kind, confirm }).catch(() => ({ ok: false as const, error: "Could not send the request." }));
    if (!r.ok) { setMsg({ ok: false, t: r.error }); return; }
    setMsg({ ok: true, t: kind === "export" ? "Export requested. We email you a download link when it is ready." : "Deletion requested. We confirm by email before anything is deleted." });
    setConfirm(""); router.refresh();
  };
  const cancel = async (id: string) => { const r = await cancelDataRequestAction(id).catch(() => ({ ok: false as const, error: "Could not cancel." })); if (!r.ok) setMsg({ ok: false, t: r.error }); else router.refresh(); };
  return (
    <div style={{ display: "grid", gap: 18 }}>
      <div className="cx-grid">
        <div className="cx-card cx-s6" style={{ display: "grid", gap: 10, alignContent: "start" }}>
          <h3 className="cx-h2">Export my Cyrus data</h3>
          <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Projects, prompts, builds and their source, revisions, studio assets you made, token history and settings, as one archive.</p>
          <div><button type="button" className="cx-btn" onClick={() => run("export")}>Request export</button></div>
        </div>
        <div className="cx-card cx-s6" style={{ display: "grid", gap: 10, alignContent: "start" }}>
          <h3 className="cx-h2">Delete my Cyrus data</h3>
          <p className="cx-muted" style={{ margin: 0, fontSize: 13 }}>Removes your Cyrus projects, builds, assets and keys. Your Nxeon account, servers and invoices are not affected; close those at Nxeon.</p>
          <label className="cx-label">Type <b className="cx-mono">{confirmPhrase}</b> to confirm<input className="cx-input" value={confirm} onChange={(e) => setConfirm(e.target.value)} autoComplete="off" /></label>
          <div><button type="button" className="cx-btn cx-btn-danger" disabled={confirm.trim().toLowerCase() !== confirmPhrase} onClick={() => run("delete")}>Request deletion</button></div>
        </div>
      </div>
      {msg ? <p className={msg.ok ? "cx-okmsg" : "cx-error"} role="status" style={{ margin: 0 }}>{msg.t}</p> : null}
      {requests.length ? (
        <div className="cx-list">
          {requests.map((r) => (
            <div key={r.id} className="cx-row">
              <span className="cx-grow"><span className="cx-t" style={{ display: "block" }}>{r.kind === "export" ? "Export" : "Deletion"}</span><span className="cx-d" style={{ display: "block" }}>requested {date(r.createdAt)}</span></span>
              <span className={`cx-pill ${r.status === "done" ? "cx-ok" : r.status === "cancelled" ? "cx-none" : "cx-wait"}`}>{r.status.replace("_", " ")}</span>
              {r.status === "requested" ? <button type="button" className="cx-btn cx-btn-sm" onClick={() => cancel(r.id)}>Cancel</button> : null}
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

export function RevokeGrant({ serverId }: { serverId: string }) {
  const router = useRouter();
  const [err, setErr] = useState<string | null>(null);
  return <>{err ? <span className="cx-error">{err}</span> : null}<button type="button" className="cx-btn cx-btn-sm cx-btn-danger" onClick={async () => { if (!confirm("Disconnect Cyrus from this server?")) return; const r = await revokeGrantAction(serverId).catch(() => ({ ok: false as const, error: "Could not revoke." })); if (!r.ok) setErr(r.error); else router.refresh(); }}>Disconnect</button></>;
}

