// Cyrus customer app (r39): pure logic of keys, prefs, data requests, grants, view models, flags and host routing.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createKey, verifyKey, memoryKeyStore, parseScopes, PERSONAL_SCOPES, MAX_ACTIVE_KEYS, sha256Hex, toView } from "../lib/cyrus/app/apikeys";
import { defaultPrefs, readPrefs, prefsFromForm, NOTIFY_EVENTS } from "../lib/cyrus/app/prefs";
import { requestData, memoryDataStore, DELETE_CONFIRM } from "../lib/cyrus/app/data-requests";
import { unavailableGrants, memoryGrants, grantsProvider, setGrantsProvider, GRANT_SCOPES } from "../lib/cyrus/app/grants";
import { flightBadge, activityFeed, contributionCounts, projectCards, buildRows, ago } from "../lib/cyrus/app/view";
import { customerAppEnabled, appHref, APP_BASE } from "../lib/cyrus/app/flags";
import { bridgeConfig } from "../lib/cyrus/bridge/config";
import { cyrusHostRoute, safeCyrusNext, appPath } from "../lib/cyrus/bridge/routing";
import { groupProjects } from "../lib/cyrus/projects";
import type { ModBuildView } from "../lib/cyrus/builder/types";

const build = (o: Partial<ModBuildView> & { id: string }): ModBuildView => ({
  status: "succeeded", prompt: "A /heal command", changeRequest: null, baseBuildId: null, rootBuildId: null, mcVersion: "1.21.11", pluginName: "Heal", version: "1.0.0",
  error: null, errorCode: null, attempts: 1, durationMs: 1000, jarName: "heal.jar", jarSize: 10, createdAt: "2026-10-01T10:00:00.000Z", finishedAt: "2026-10-01T10:02:00.000Z",
  result: null, lastInstall: null, cyrus: null, ...o,
});

describe("personal API keys", () => {
  it("creates a key shown once, stores only its sha256, verifies it and records use", async () => {
    const s = memoryKeyStore();
    const r = await createKey(s, "u1", { name: "CI", scopes: ["projects:read", "builds:read"], expiryDays: 30 });
    assert.ok(r.ok);
    if (!r.ok) return;
    assert.match(r.key, /^cyk_[A-Za-z0-9]{8}_[A-Za-z0-9]{40}$/);
    assert.equal(s.rows[0].sha256, sha256Hex(r.key));
    assert.ok(!JSON.stringify(s.rows).includes(r.key), "the plain key is never stored");
    const v = await verifyKey(s, r.key);
    assert.deepEqual(v && { u: v.userId, sc: v.scopes }, { u: "u1", sc: ["projects:read", "builds:read"] });
    assert.ok(s.rows[0].lastUsedAt);
  });
  it("fails closed: malformed, unknown, revoked, expired, wrong prefix", async () => {
    const s = memoryKeyStore();
    const r = await createKey(s, "u1", { name: "k", scopes: ["mods:read"], expiryDays: 30 });
    assert.ok(r.ok); if (!r.ok) return;
    assert.equal(await verifyKey(s, "nope"), null);
    assert.equal(await verifyKey(s, r.key.replace(/.$/, (c) => (c === "a" ? "b" : "a"))), null);
    assert.equal(await verifyKey(s, r.key, new Date(Date.now() + 31 * 86_400_000)), null, "expired");
    assert.equal(await s.revoke("someone-else", s.rows[0].id, new Date()), false, "another user cannot revoke it");
    assert.ok(await s.revoke("u1", s.rows[0].id, new Date()));
    assert.equal(await verifyKey(s, r.key), null, "revoked");
  });
  it("never grants staff scopes, rejects unknown ones and empty sets", () => {
    assert.ok(!(PERSONAL_SCOPES as readonly string[]).includes("admin:read"));
    assert.equal(parseScopes(["admin:read"]).ok, false);
    assert.equal(parseScopes(["projects:read", "rm -rf"]).ok, false);
    assert.equal(parseScopes([]).ok, false);
    const ok = parseScopes(["builds:read", "projects:read", "builds:read"]);
    assert.deepEqual(ok.ok && ok.scopes, ["projects:read", "builds:read"]);
  });
  it("caps active keys, validates name and expiry", async () => {
    const s = memoryKeyStore();
    for (let i = 0; i < MAX_ACTIVE_KEYS; i++) assert.ok((await createKey(s, "u1", { name: `k${i}`, scopes: ["mods:read"] })).ok);
    const over = await createKey(s, "u1", { name: "one more", scopes: ["mods:read"] });
    assert.equal(over.ok, false);
    assert.ok((await createKey(s, "u2", { name: "other user", scopes: ["mods:read"] })).ok, "the cap is per user");
    assert.equal((await createKey(s, "u2", { name: "", scopes: ["mods:read"] })).ok, false);
    assert.equal((await createKey(s, "u2", { name: "x".repeat(49), scopes: ["mods:read"] })).ok, false);
    assert.equal((await createKey(s, "u2", { name: "x", scopes: ["mods:read"], expiryDays: 7 })).ok, false);
    const forever = await createKey(s, "u2", { name: "forever", scopes: ["mods:read"], expiryDays: 0 });
    assert.ok(forever.ok && forever.view.expiresAt === null);
  });
  it("views never carry the hash", async () => {
    const s = memoryKeyStore();
    await createKey(s, "u1", { name: "k", scopes: ["mods:read"] });
    const v = toView(s.rows[0], new Date());
    assert.ok(!("sha256" in v));
    assert.equal(v.active, true);
  });
});

describe("notification prefs", () => {
  it("defaults, drops unknown keys and keeps takedown notices on", () => {
    const d = defaultPrefs();
    assert.equal(d.product_news.email, false);
    const p = readPrefs({ takedown: { email: false, inApp: false }, build_finished: { email: false }, bogus: { email: true } });
    assert.deepEqual(p.takedown, { email: true, inApp: true });
    assert.deepEqual(p.build_finished, { email: false, inApp: true });
    assert.ok(!("bogus" in p));
    assert.deepEqual(readPrefs("garbage"), defaultPrefs());
  });
  it("a form with nothing ticked turns everything off except the locked event", () => {
    const p = prefsFromForm([]);
    for (const e of NOTIFY_EVENTS) assert.deepEqual(p[e.id], e.locked ? { email: true, inApp: true } : { email: false, inApp: false });
    assert.equal(prefsFromForm([["mod_outdated.email", "on"]]).mod_outdated.email, true);
  });
});

describe("data requests", () => {
  it("one open request per kind; deletion needs the typed confirmation; cancel only own + not started", async () => {
    const s = memoryDataStore();
    assert.ok((await requestData(s, "u1", { kind: "export" })).ok);
    assert.equal((await requestData(s, "u1", { kind: "export" })).ok, false);
    assert.equal((await requestData(s, "u1", { kind: "delete", confirm: "yes" })).ok, false);
    assert.ok((await requestData(s, "u1", { kind: "delete", confirm: DELETE_CONFIRM.toUpperCase() })).ok);
    assert.equal((await requestData(s, "u1", { kind: "wipe-everything" })).ok, false);
    assert.equal(await s.cancel("u2", s.rows[0].id), false);
    assert.ok(await s.cancel("u1", s.rows[0].id));
    assert.ok((await requestData(s, "u1", { kind: "export" })).ok, "after cancelling a new one can be made");
  });
});

describe("grants (plan 3.3 contract)", () => {
  it("defaults to unavailable and never claims a revoke", async () => {
