    assert.equal(await s.cancel("u2", s.rows[0].id), false);
    assert.ok(await s.cancel("u1", s.rows[0].id));
    assert.ok((await requestData(s, "u1", { kind: "export" })).ok, "after cancelling a new one can be made");
  });
});

