// Cyrus r31 screens (Mod Packs, Import, Data packs): seed the devhost THROWAWAY database for the studio test account
// usr_studio_all (run AFTER scripts/cyrus/studio-fixtures.ts): three plugin mods with real stored jars (two claim /shop,
// so the conflict engine has a real warning), a "Frostlands" mod with two data pack specs (the worldgen showcase + a
// plain recipe/loot pack) recorded like a build's asset sync, and one Paper 1.21.11 server row. Jars go to
// $NXEON_MODBUILD_DIR/r31-fx. Prints { packs: [buildIds], datapacks: buildId, server }.
// Refuses to run against anything but devhost's wt_* database on 127.0.0.1:5433.
//   NXEON_MODBUILD_DIR=/tank/nxeon-build/tmp/cyrus-r31/mb devhost run -- npx tsx scripts/cyrus/forge-fixtures.ts
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { db } from "../../lib/db";
import { zip } from "../../lib/cyrus/textures/zip";
import { canonicalJson, sha256Hex } from "../../lib/cyrus/assets/textures";
import { addRevision, createProject, recordAsset } from "../../lib/cyrus/engine-core/store";
import { buildDataPack } from "../../lib/cyrus/datapack/emit";
import { cyrusConfig } from "../../lib/cyrus/config";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
const USER = "usr_studio_all";
const V = "1.21.11";
const FX = path.join(cyrusConfig().modbuildDir, "r31-fx");
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const PLUGINS = [
  { name: "VoidArsenal", title: "Void Arsenal", cmds: { voidarsenal: {} } },
  { name: "GuildCraft", title: "Guild Craft", cmds: { guildcraft: { aliases: ["shop"] } } },
  { name: "ShopPlus", title: "Shop Plus", cmds: { shop: {} } },
];

async function main() {
  mkdirSync(FX, { recursive: true });
  const user = await db.user.findUnique({ where: { id: USER } });
  if (!user) throw new Error("run scripts/cyrus/studio-fixtures.ts first");
  const out: { packs: string[]; datapacks: string | null; server: string | null } = { packs: [], datapacks: null, server: null };
  for (const p of PLUGINS) {
    const id = `mbr31${p.name.toLowerCase()}`.slice(0, 30);
    const yml = `name: ${p.name}\nversion: 1.0.0\nmain: dev.nxeon.plugins.${p.name.toLowerCase()}.${p.name}\napi-version: '1.21'\ncommands:\n${Object.entries(p.cmds).map(([c, o]) => `  ${c}:\n    description: ${p.title}${(o as { aliases?: string[] }).aliases ? `\n    aliases: [${(o as { aliases: string[] }).aliases.join(", ")}]` : ""}`).join("\n")}\n`;
    const jar = zip([{ path: "plugin.yml", data: Buffer.from(yml) }, { path: `dev/nxeon/plugins/${p.name.toLowerCase()}/${p.name}.class`, data: Buffer.from([0xca, 0xfe, 0xba, 0xbe]) }]);
    const jarPath = path.join(FX, `${id}.jar`);
    writeFileSync(jarPath, jar);
    await db.modBuild.deleteMany({ where: { id } });
    await db.modBuild.create({ data: { id, userId: USER, prompt: `${p.title} (r31 fixture)`, mcVersion: V, pluginName: p.name, status: "succeeded", jarName: `${p.name}-1.0.0.jar`, jarPath, jarSha256: sha(jar), cyrus: { title: p.title }, finishedAt: new Date() } as never });
    await db.cyrusProject.deleteMany({ where: { rootBuildId: id } }).catch(() => undefined);
    await createProject({ userId: USER, game: "minecraft", title: p.title, rootBuildId: id });
    out.packs.push(id);
  }
  // Frostlands: two data pack specs, recorded like the build sync records them
