  await mk("mbappbounty2", { prompt: "", changeRequest: "Fix the crash on enable and add a 10 minute cooldown per target", rootBuildId: "mbappbounty", baseBuildId: "mbappbounty", pluginName: "BountyHunt", version: "1.1.0", status: "succeeded", jarName: "BountyHunt-1.1.0.jar", createdAt: ago(60 * 20), finishedAt: ago(60 * 20 - 4), lastInstall: { serverId: "x", serverName: "guild-survival", at: ago(60 * 19).toISOString(), replaced: [], restarted: true }, cyrus: { testFlight: flight("passed", "Passed on Paper 1.21.11") } });
  await mk("mbappbounty3", { prompt: "", changeRequest: "Show the bounty board as a sidebar while a bounty is active", rootBuildId: "mbappbounty", baseBuildId: "mbappbounty2", pluginName: "BountyHunt", status: "coding", createdAt: ago(2) });
  await mk("mbappboss", { prompt: "An ice wyvern boss with three phases, a frost breath attack and a loot chest", pluginName: null, status: "failed", error: "The build did not compile after 3 repair attempts.", createdAt: ago(60 * 5), finishedAt: ago(60 * 5 - 6) });
  const proj = await createProject({ userId: USER, game: "minecraft", title: "Bounty Hunt", rootBuildId: "mbappbounty" });
  await addRevision(proj.id, { kind: "generated", status: "failed", modBuildId: "mbappbounty", manifest: [], message: "First build" } as never);
  await addRevision(proj.id, { kind: "generated", status: "passed", modBuildId: "mbappbounty2", manifest: [], message: "Crash fix + cooldown" } as never);
  await addRevision(proj.id, { kind: "edited", status: "passed", manifest: [], message: "Cooldown 600 -> 300 in the config studio" } as never);

  // servers: a running Paper (ready) and a stopped one
  const plan = await db.plan.upsert({ where: { slug: "r39fx" }, create: { slug: "r39fx", name: "r39", cpuCores: 1, ramMB: 4096, diskGB: 10, priceCents: 1 }, update: {} });
  const os = await db.osTemplate.upsert({ where: { slug: "r39fx-mc" }, create: { slug: "r39fx-mc", name: "Minecraft", vmid: 1, family: "minecraft" }, update: {} });
  const gp = await db.gamePlan.findFirst({ where: { name: "r39fx" } }) ?? await db.gamePlan.create({ data: { gameFamily: "minecraft", name: "r39fx", ramMB: 4096, diskGB: 10, priceCents: 1, basePlanId: plan.id } as never });
  for (const [name, status] of [["guild-survival", "RUNNING"], ["creative-build", "STOPPED"]] as const) {
    if (!(await db.server.findFirst({ where: { userId: USER, name } }))) await db.server.create({ data: { name, hostname: `${name}.test`, userId: USER, planId: plan.id, osTemplateId: os.id, gamePlanId: gp.id, status, gameVariant: "paper", gameConfig: { VERSION: V } } as never });
  }

  // token ledger (history rows for the activity feed)
  await db.cyrusTokenLedger.deleteMany({ where: { userId: USER, idemKey: { startsWith: "r39fx:" } } });
  let bal = 2400;
  for (const [i, kind, delta, source, min] of [[1, "grant", 2500, "plan", 60 * 40], [2, "spend", -96, null, 60 * 30], [3, "spend", -132, null, 60 * 20], [4, "grant", 500, "topup", 60 * 8]] as const) {
    bal += delta;
    await db.cyrusTokenLedger.create({ data: { userId: USER, kind, delta, balanceAfter: bal, idemKey: `r39fx:${i}`, source, createdAt: ago(min) } as never });
  }

  // library contributions
  await db.cyrusCatalogEntry.deleteMany({ where: { contributorId: USER } });
  for (const [i, title, status] of [[1, "Frost sword (16x16)", "published"], [2, "Bounty board icon", "published"], [3, "Wyvern roar", "held"], [4, "Ice brick texture", "pending-checks"]] as const) {
    const id = `${"r39fx".padEnd(8, "0")}${String(i).padStart(56, "0")}`;
    await db.cyrusCatalogEntry.create({ data: { id, kind: i === 3 ? "sound" : "texture", status, tier: "user-contributed", primaryCat: "items", quality: 70, enrichedBy: "contributor", coverage: "partial", source: "contribution", contributorId: USER, searchText: title, entry: { title }, createdAt: ago(60 * (50 - i * 10)) } as never });
  }

  // one API key + one data request
  await db.cyrusPersonalApiKey.deleteMany({ where: { userId: USER } });
  await createKey(prismaKeyStore, USER, { name: "Server sync bot", scopes: ["projects:read", "builds:read", "installs:read"], expiryDays: 90 });
  await db.cyrusDataRequest.deleteMany({ where: { userId: USER } });
  await db.cyrusDataRequest.create({ data: { userId: USER, kind: "export", status: "done", createdAt: ago(60 * 24 * 9), completedAt: ago(60 * 24 * 8) } });
  console.log(JSON.stringify({ ok: true, project: "mbappbounty", failed: "mbappboss" }));
  await db.$disconnect();
}
main().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

