describe("app grants provider over the r38 Nxeon grants", () => {
  it("off = unavailable; on = the user's own active grants, revoke only their own", async () => {
    const { appGrants } = await import("../app/dashboard/cyrus/app/_grants");
    const g = await import("../lib/nxeon-platform/grants");
    const prev = process.env.CYRUS_SERVER_GRANTS;
    delete process.env.CYRUS_SERVER_GRANTS;
    assert.equal((await appGrants("https://nxeon.example").state("u1")).available, false);
    process.env.CYRUS_SERVER_GRANTS = "1";
    const store = g.createMemoryGrantStore(); g.setGrantStoreForTests(store);
    try {
      const now = new Date();
      await store.upsert({ client: "cyrus", userId: "u1", serverId: "s1", scopes: ["servers.read", "inventory.read"], consentVersion: "t", now });
      await store.upsert({ client: "cyrus", userId: "u2", serverId: "s2", scopes: ["servers.read"], consentVersion: "t", now });
      const p = appGrants("https://nxeon.example");
      const st = await p.state("u1");
      assert.ok(st.available);
      if (!st.available) return;
      assert.deepEqual(st.grants.map((x) => [x.serverId, x.scopes]), [["s1", ["servers.read", "inventory.read"]]]);
      assert.equal(st.connectUrl("s 1"), "https://nxeon.example/dashboard/connect/cyrus?server=s%201");
      assert.equal(await p.revoke("u1", "s2"), false, "cannot revoke another user's grant");
      assert.equal(await p.revoke("u1", "s1"), true);
      const after = await p.state("u1");
      assert.ok(after.available && after.grants.length === 0);
    } finally {
      g.setGrantStoreForTests(null);
      if (prev === undefined) delete process.env.CYRUS_SERVER_GRANTS; else process.env.CYRUS_SERVER_GRANTS = prev;
    }
  });
});
EOF
